window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch02"]={"id": "ch02", "title": "第二章 生物学数据库及其检索", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第二章 生物学数据库及其检索", "slides": [{"i": 0, "sec": "第一节 生物学数据库简介", "title": "生物学数据库简介：数据库概念、记录结构与数据库类型", "notes": "本页开启第二章，指出随着生物学和各类组学技术发展，生物学数据呈指数增长，如何建立与使用数据库进行大批量数据存储、处理和检索，是生物信息学最基本任务之一。本章将介绍生物数据库的类型、内容与结构，以及通过 Entrez 和 SRS 进行综合检索。第一节首先定义数据库：数据库是用于存储和管理数据的计算机文档，是统一管理的相关数据集合，其存储形式便于检索与调用。数据库开发的核心任务是把数据组织为结构化记录，以便信息检索。每条记录又称条目，包含多个字段，字段描述某类数据特性或属性，如基因名、来源物种、序列创建日期等；值是字段的具体内容。检索就是利用查询语言在整个数据库中查找满足条件的所有记录，例如在 GenBank 中查找人源、最近30天公布、mRNA 类型的核酸序列。数据库结构类型包括平面文件、关系型数据库、面向对象数据库和基于 Internet 平台的 XML；最早数据库采用平面文件格式。掌握记录、字段、值、条目和检索条件等术语。", "page": 11, "level": "掌握", "img": "assets/img/ch02/p011.jpg", "anim": null, "fig": null, "points": ["生物学数据随组学技术发展呈指数增长，数据库的建立与使用是生物信息学最基本任务之一", "数据库是用于存储和管理数据的计算机文档，是统一管理的相关数据集合", "数据库存储形式便于检索与调用", "本章介绍数据库类型、内容与结构，以及Entrez和SRS综合检索", "⚠️ 考点/易错点：数据库的核心是把数据组织为结构化记录（条目），便于检索与调用；易混点：数据库是统一管理的相关数据集合，而非简单文件堆砌。"], "code": null, "check": {"q": "根据第一节对数据库的定义，数据库开发的核心任务是什么？", "o": ["A. 把数据随机存入计算机文档以便长期保存", "B. 把数据组织为结构化记录以便信息检索", "C. 把数据压缩为最小字节数以便节省空间", "D. 把数据转换为图像以便直观展示"], "a": "B", "e": "页面指出数据库是统一管理的相关数据集合，其存储形式便于检索与调用；数据库开发的核心任务是把数据组织为结构化记录，以便信息检索。"}, "cards": [{"front": "什么是数据库？", "back": "数据库是用于存储和管理数据的计算机文档，是统一管理的相关数据集合，其存储形式便于检索与调用。", "mnemonic": "数据库=统一管理的相关数据集合，便于检索调用", "useImg": false}]}, {"i": 1, "sec": "第一节 生物学数据库简介", "title": "生物学数据库分类：一级数据库与二级数据库", "notes": "本页承接数据库结构类型，提到关系型数据库管理系统，并指出其详细内容见本章第二节及第十三章第三节。2003年4月人类基因组计划主要目标完成，获得完整、准确、高质量人类基因组序列，对生物学与生物医学研究产生深远影响。人类基因组序列数据及其他模式生物序列数据、基因结构与功能信息可免费接入使用，为实验设计与解释提供背景知识。生物学数据库类型多样：按存放数据类型可分为序列数据库（GenBank、Swiss-Prot 等）、三维结构数据库（PDB）、文献数据库（NCBI PubMed）、序列特征数据库（PROSITE、Pfam 等）、基因组图谱数据库（MapViewer、Ensembl 等）、表达谱数据库等，每类还可细分。按存储内容可分为一级数据库和二级数据库，以及针对性更强的专用数据库。一级数据库属于档案数据库，主要内容是实验室操作得到的原始数据结果，如测序得到的序列或 X 射线晶体衍射得到的三维结构数据，也包含基本说明，如物种、类型、发表文献出处等。核酸序列数据库 GenBank、EMBL、DDBJ 及蛋白质结构数据库 PDB 是典型一级数据库。理解一级与二级数据库区别。", "page": 12, "level": "理解", "img": "assets/img/ch02/p012.jpg", "anim": null, "fig": null, "points": ["2003年4月人类基因组计划主要目标完成，获得完整准确高质量人类基因组序列", "人类基因组及其他模式生物序列数据、基因结构与功能信息可免费接入使用", "生物学数据库按存放数据类型可分为一级数据库与二级数据库", "关系型数据库管理系统详细内容见本章第二节及第十三章第三节", "⚠️ 考点/易错点：一级数据库存原始数据（如GenBank、Swiss-Prot、PDB），二级数据库是在一级数据基础上经加工整合而成；易错：Swiss-Prot常被误认为二级库，实际为一级蛋白序列库。"], "code": null, "check": {"q": "按存放数据类型划分，下列哪一组数据库分别属于序列数据库和三维结构数据库？", "o": ["A. GenBank、PDB", "B. PDB、Swiss-Prot", "C. PubMed、GenBank", "D. Swiss-Prot、PubMed"], "a": "A", "e": "页面说明按存放数据类型可分为序列数据库（GenBank、Swiss-Prot 等）和三维结构数据库（PDB）等，因此 GenBank 属序列数据库，PDB 属三维结构数据库。"}, "cards": [{"front": "生物学数据库按存放数据类型可分为哪两类？", "back": "一级数据库和二级数据库。", "mnemonic": "一级原始，二级加工", "useImg": false}]}, {"i": 2, "sec": "第一节 生物学数据库简介", "title": "生物信息学资源查找方法与重要门户站点", "notes": "本页讨论面对海量生物资源时如何找到与研究相关的数据库和工具。常用方法有三：第一，利用公共搜索引擎。数据库网页通常含有关键词，可用研究相关关键词搜索；但关键词不唯一，不同搜索引擎对多个检索词的默认组合关系不同，如对 alcoholic disease 可能按短语、交集或并集处理，导致结果歧义。因此公共引擎最简单也最容易产生歧义；若已知准确资源名称或简称别名，如 National Center for Biotechnology Information 或 NCBI，则公共搜索引擎可快速获得确定网址 URL。第二，了解重要生物信息学门户站点。NCBI、欧洲生物信息研究所 EBI、瑞士生物信息研究所 SIB 维护的 ExPASy 等都是重要门户，提供多种数据库、分析工具、教程，并链接大量非自身维护资源，是分子生物学研究最基础的批量数据来源。第三，利用 Nucleic Acid Research 杂志每年的数据库专辑/网络服务器专辑，系统了解新数据库和工具。掌握这些检索策略和门户资源。", "page": 13, "level": "掌握", "img": "assets/img/ch02/p013.jpg", "anim": null, "fig": null, "points": ["查找生物信息学资源常用方法有三：公共搜索引擎、已知资源名称或简称别名、重要门户站点", "公共搜索引擎最简单但最容易产生歧义，不同引擎对多个检索词默认组合关系不同", "已知准确资源名称或简称别名时可直接访问或检索", "重要门户站点如NCBI、EBI等是资源查找的重要入口", "⚠️ 考点/易错点：公共搜索引擎检索多关键词时默认组合关系因引擎而异（短语/交集/并集），最易产生歧义；已知准确资源名称或简称时应优先用专门门户或直接访问。"], "code": null, "check": {"q": "关于利用公共搜索引擎查找生物信息学资源，下列说法正确的是？", "o": ["A. 公共搜索引擎不会产生歧义，因为检索词总是唯一匹配", "B. 不同搜索引擎对多个检索词的默认组合关系相同，均按短语处理", "C. 公共搜索引擎最简单，但也最容易产生歧义", "D. 若已知准确资源名称或简称别名，也应优先使用公共搜索引擎而非直接访问"], "a": "C", "e": "页面指出公共引擎最简单也最容易产生歧义；不同搜索引擎对多个检索词默认组合关系不同，如可能按短语、交集或并集处理；若已知准确资源名称或简称别名，可直接访问。"}, "cards": [{"front": "查找生物信息学资源的常用方法有哪些？", "back": "三种：利用公共搜索引擎；已知准确资源名称或简称别名直接访问；利用重要门户站点。", "mnemonic": "搜、名、站", "useImg": false}]}, {"i": 3, "sec": "第一节 生物学数据库简介", "title": "NAR 数据库专辑分类：结构、基因组、代谢与信号途径等", "notes": "本页为 NAR 数据库专辑分类表的一部分，按英文名和中文名列出多类数据库。结构数据库包括小分子结构、碳水化合物结构、核酸结构、蛋白质结构。基因组数据库（非脊椎动物）包括基因组注释术语、语义及系统命名，生物分类与定义，通用基因组学数据库，病毒基因组数据库，原核生物基因组数据库，单细胞真核生物基因组数据库，真菌基因组数据库，无脊椎动物基因组数据库等。代谢与信号途径数据库包括酶与酶的系统命名、代谢途径、蛋白质-蛋白质互作、信号途径。人类及其他脊椎动物基因组数据库包括模式生物等。该表用于帮助读者按研究对象和数据类型定位相应数据库。读表时应先看大类，再看具体数据库类型；注意结构数据库侧重分子三维结构，基因组数据库侧重基因组序列、注释、分类和命名，代谢与信号途径数据库侧重通路和互作。了解该分类体系有助于选择合适数据源。", "page": 14, "level": "了解", "img": "assets/img/ch02/p014.jpg", "anim": null, "fig": null, "points": ["NAR数据库专辑按英文名和中文名列出了多类数据库", "结构数据库包括小分子结构、碳水化合物结构、核酸结构、蛋白质结构", "基因组数据库（非脊椎动物）包括基因组注释术语、语义及系统命名，生物分类与定义，通用基因组学数据库，病毒、原核生物、单细胞真核生物、真菌、无脊椎动物基因组数据库等", "代谢与信号途径等也是NAR数据库专辑的分类之一", "⚠️ 考点/易错点：NAR数据库专辑按结构、基因组、代谢与信号途径等分类；易混：结构数据库含小分子、碳水化合物、核酸、蛋白质结构，而代谢与信号途径库侧重酶、代谢途径、蛋白互作与信号途径。"], "code": null, "check": {"q": "在 NAR 数据库专辑分类中，下列哪项属于“代谢与信号途径数据库”类别？", "o": ["A. 蛋白质结构", "B. 核酸结构", "C. 酶与酶的系统命名", "D. 病毒基因组数据库"], "a": "C", "e": "页面列出代谢与信号途径数据库包括酶与酶的系统命名、代谢途径、蛋白质-蛋白质互作、信号途径；蛋白质结构、核酸结构属于结构数据库，病毒基因组数据库属于基因组数据库。"}, "cards": [{"front": "NAR数据库专辑中结构数据库包括哪些？", "back": "小分子结构、碳水化合物结构、核酸结构、蛋白质结构。", "mnemonic": "小碳核酸蛋白", "useImg": false}]}, {"i": 4, "sec": "第一节 生物学数据库简介", "title": "NAR 网络服务器分类：计算机、序列分析与表达分析工具", "notes": "本页为 NAR 网络服务器分类表，按英文和中文列出网络服务器类别。计算机相关包括生物编程工具、C/C++、数据库类、Java、Linux/Unix、PERL、PHP、统计学、网络开发、网络服务。DNA 相关包括注释、基因预测、作图和序列装配、重建系统发育关系、序列特性检测、序列多态性、序列检索与提交。实验室使用的分析工具包括教育、生物信息学相关新闻资源、社团、课程/项目/研讨会、机构名录及入口、通用、指南及有指导的学习资源。表达相关包括 cDNA、EST、SAGE、基因调控、网络、蛋白质表达等。该表说明 NAR 网络服务器专辑不仅收录分析工具，也收录教育、新闻、社区和编程资源。读表时可按任务分类：若做基因预测、序列装配、系统发育重建、序列多态性分析，可在 DNA 类中查找；若做表达分析，可在 Expression 类中查找；若需编程或统计支持，可在 Computer Related 中查找。了解该分类有助于快速定位在线工具。", "page": 15, "level": "了解", "img": "assets/img/ch02/p015.jpg", "anim": null, "fig": null, "points": ["NAR网络服务器分类包括计算机相关、DNA相关、实验室使用的分析工具等", "计算机相关包括生物编程工具、C/C++、数据库类、Java、Linux/Unix、PERL、PHP、统计学、网络开发、网络服务", "DNA相关包括注释、基因预测、作图和序列装配、重建系统发育关系、序列特性检测、序列多态性、序列检索与提交", "实验室使用的分析工具包括教育、生物信息学相关新闻资源、社团等", "⚠️ 考点/易错点：NAR网络服务器分类中DNA相关工具包括注释、基因预测、作图和序列装配、序列特性检测等；易错：序列检索与提交也归入DNA相关，而非数据库类。"], "code": null, "check": {"q": "在 NAR 网络服务器分类中，下列哪项属于“计算机相关”类别？", "o": ["A. 基因预测", "B. 序列装配", "C. 数据库类", "D. 序列多态性"], "a": "C", "e": "页面列出计算机相关包括生物编程工具、C/C++、数据库类、Java、Linux/Unix、PERL、PHP、统计学、网络开发、网络服务；基因预测、序列装配、序列多态性属于 DNA 相关。"}, "cards": [{"front": "NAR网络服务器分类中计算机相关包括哪些？", "back": "生物编程工具、C/C++、数据库类、Java、Linux/Unix、PERL、PHP、统计学、网络开发、网络服务。", "mnemonic": "编程语言加统计网络", "useImg": false}]}, {"i": 5, "sec": "第一节 生物学数据库简介", "title": "NAR 网络服务器分类续：模式生物、其他分子与蛋白质工具", "notes": "本页继续列出 NAR 网络服务器分类表。模式生物包括鱼、果蝇、通用资源、微生物、小鼠与大鼠、其他生物、其他脊椎动物、植物、线虫、酵母。其他分子包括碳水化合物、复合物、代谢物、小分子、蛋白质。蛋白质相关工具包括二维结构预测、三维结构特征、三维结构比较、三维结构预测、三维结构检索与浏览、生化小分子特性、蛋白质全方位预测工具、结构域与基序、互作/途径/酶、定位与定向、分子动力学与分子对接、重建系统发育、表示方式与格式、蛋白质表达、蛋白质组学等。该表体现网络服务器按研究对象和功能分类：模式生物类便于按物种查找资源；其他分子类覆盖小分子、代谢物和蛋白质；蛋白质类进一步按结构预测、结构比较、结构检索、结构域、互作、定位、对接、系统发育、表达和蛋白质组学细分。读表时应根据研究对象的物种或分子类型，以及所需分析功能，定位相应服务器类别。了解该分类可提高资源检索效率。", "page": 16, "level": "了解", "img": "assets/img/ch02/p016.jpg", "anim": null, "fig": null, "points": ["NAR网络服务器分类续包括模式生物、其他分子、蛋白质相关工具", "模式生物包括鱼、果蝇、通用资源、微生物、小鼠与大鼠、其他生物、其他脊椎动物、植物、线虫、酵母", "其他分子包括碳水化合物、复合物、代谢物、小分子、蛋白质", "蛋白质相关工具包括二维结构预测、三维结构特征、三维结构比较、三维结构预测、三维结构检索与浏览、生化小分子特性、蛋白质全方位预测工具、结构域与基序、互作/途径/酶、定位与定等", "⚠️ 考点/易错点：模式生物网络服务器按鱼、果蝇、微生物、小鼠大鼠、植物、线虫、酵母等分类；蛋白质工具涵盖二维/三维结构预测、结构域与基序、互作/途径/酶等，注意区分结构预测与结构比较。"], "code": null, "check": {"q": "在 NAR 网络服务器分类中，下列哪项属于“模式生物”类别？", "o": ["A. 鱼", "B. 碳水化合物", "C. 分子动力学与分子对接", "D. 蛋白质表达"], "a": "A", "e": "页面列出模式生物包括鱼、果蝇、通用资源、微生物、小鼠与大鼠、其他生物、其他脊椎动物、植物、线虫、酵母；碳水化合物属于其他分子，分子动力学与分子对接、蛋白质表达属于蛋白质相关工具。"}, "cards": [{"front": "NAR网络服务器分类中蛋白质相关工具包括哪些？", "back": "二维结构预测、三维结构特征、三维结构比较、三维结构预测、三维结构检索与浏览、生化小分子特性、蛋白质全方位预测工具、结构域与基序、互作/途径/酶、定位与定等。", "mnemonic": "二三维结构预测比较检索，加上功能预测", "useImg": false}]}, {"i": 6, "sec": "第一节 生物学数据库简介", "title": "重要生物信息站点：NCBI与EBI简介", "notes": "本页属于第一节“生物学数据库简介”，主要介绍重要生物信息站点。首先指出NAR数据库专辑和网络服务器专辑因收集数据库与分析工具数量庞大、范围广，是生物学数据资源及分析工具开发与更新的信息聚集地，可为实验学家和生物信息学家提供可靠信息来源。随后重点介绍NCBI：美国国家生物技术信息中心（National Center for Biotechnology Information），成立于1988年11月4日，隶属于美国国立卫生研究院（NIH）下的美国国家医学图书馆（NLM）。其主要任务是创建公共可访问的数据库，引导计算生物学及基因组数据分析软件开发，并发布各类生物医学信息。NCBI已成为世界级生物信息资源中心，常用资源包括PubMed、GenBank、BLAST、MapViewer等。NCBI数据资源主要包括数据库、数据下载、数据提交及分析工具四部分，另有How To页面说明主要数据库或工具使用方法。全部资源可通过NCBI主页All Resources界面查找和了解。页末开始介绍EBI（欧洲生物信息研究所），为下一页内容作铺垫。", "page": 17, "level": "掌握", "img": "assets/img/ch02/p017.jpg", "anim": null, "fig": null, "points": ["NAR数据库专辑和网络服务器专辑是生物学数据资源及分析工具开发与更新的信息聚集地", "NCBI是美国国家生物技术信息中心（National Center for Biotechnology Information）", "NCBI提供多种数据库和分析工具，如PubMed、GenBank、BLAST等", "EBI是欧洲生物信息学研究所，也是重要生物信息站点", "⚠️ 考点/易错点：NCBI成立于1988年11月4日，隶属NIH；NAR数据库专辑和网络服务器专辑是数据资源与分析工具开发更新的信息聚集地，常考其权威性与覆盖范围。"], "code": null, "check": {"q": "关于 NCBI 的成立时间和隶属机构，下列正确的是？", "o": ["A. 成立于1988年11月4日，隶属于美国国立卫生研究院（NIH）", "B. 成立于1990年4月1日，隶属于欧洲分子生物学实验室（EMBL）", "C. 成立于1988年11月4日，隶属于欧洲生物信息研究所（EBI）", "D. 成立于2003年4月14日，隶属于美国国立卫生研究院（NIH）"], "a": "A", "e": "页面重点介绍 NCBI：美国国家生物技术信息中心，成立于1988年11月4日，隶属于美国国立卫生研究院（NIH）。"}, "cards": [{"front": "NCBI的全称是什么？", "back": "美国国家生物技术信息中心（National Center for Biotechnology Information）。", "mnemonic": "NCBI=美国国家生物技术信息中心", "useImg": false}]}, {"i": 7, "sec": "第一节 生物学数据库简介", "title": "NCBI All Resources界面图示", "notes": "本页为整页图/表，主要展示NCBI主页中All Resources界面的资源导航结构。图中通常按资源类型或字母顺序列出NCBI提供的数据库、分析工具、下载与提交入口等，例如文献数据库PubMed、序列数据库GenBank、序列比对工具BLAST、基因组浏览工具MapViewer等。读图时应先识别页面顶部的资源分类或检索框，再按类别查找目标资源；每个资源条目一般包含名称和简要说明，点击可进入相应数据库或工具页面。该图用于说明NCBI资源丰富、组织集中，便于用户从统一入口发现和访问所需数据与分析工具。学习时应结合正文理解NCBI资源主要包括数据库、数据下载、数据提交和分析工具四部分，并知道All Resources是查找NCBI全部资源及其简介的入口。", "page": 18, "level": "了解", "img": "assets/img/ch02/p018.jpg", "anim": null, "fig": "本页为整页图/表，展示NCBI主页中All Resources界面的资源导航结构。读图时应先识别页面顶部的资源分类或检索框，再按类别查找目标资源；每个资源条目一般提供链接和简要说明。", "points": ["NCBI All Resources界面按资源类型或字母顺序列出数据库、分析工具、下载与提交入口", "常见资源包括PubMed、GenBank、BLAST、MapViewer等", "读图时先识别页面顶部的资源分类或检索框，再按类别查找目标资源", "每个资源条目一般提供链接和简要说明", "⚠️ 考点/易错点：NCBI All Resources界面按资源类型或字母顺序导航，含PubMed、GenBank、BLAST、MapViewer等；读图题易错：应先识别顶部资源分类或检索框，再按类别定位目标资源。"], "code": null, "check": {"q": "关于 NCBI All Resources 界面，读图时通常应首先识别什么？", "o": ["A. 页面底部的版权声明", "B. 页面顶部的资源分类或检索框", "C. 页面右侧的广告栏", "D. 页面中的随机推荐链接"], "a": "B", "e": "页面说明读图时应先识别页面顶部的资源分类或检索框，再按类别查找目标资源；每个资源条目一般包含名称和简要说明，点击可进入相应数据库或工具页面。"}, "cards": [{"front": "NCBI All Resources界面主要展示什么？", "back": "按资源类型或字母顺序列出NCBI提供的数据库、分析工具、下载与提交入口等。", "mnemonic": "资源导航，分类字母", "useImg": false}]}, {"i": 8, "sec": "第一节 生物学数据库简介", "title": "生物学数据库的数据存储格式概述与平面文件格式", "notes": "本页进入第二节“生物学数据库的数据存储格式”。首先说明计算机中信息以字节串形式存储，获取信息需控制两方面：数据被编译为字节的方式即数据格式，以及能够编码和解码这些数据的程序。二者紧密联系：复杂全能格式若缺乏应用程序支持则无意义；简单紧凑格式若操作功能过弱也会限制发展和普及。生物信息学中常见格式包括平面文件格式、XML格式和关系型数据库。随后介绍平面文件格式（Flat File），即纯文本文件，通常使用ASCII字符，也可包含ASCII扩展集或Unicode字符。Flat File数据库由纯文本文件构成，数据通常结构化为一组Entry（记录或条目），Entry是一组具体数据实体的描述符。例如UniProt中一个Entry包含单个蛋白质序列及其描述和特征列表。Flat File中正文行每列对应明确定义格式，Entry通常连续排列在一份或多份文本中，但排列规则不统一：有的数据库所有Entry存放在单一文本中，有的每个Entry单独存放。", "page": 19, "level": "掌握", "img": "assets/img/ch02/p019.jpg", "anim": null, "fig": null, "points": ["计算机中信息以字节串形式存储，获取信息需控制数据格式和编解码程序两方面", "数据格式与编解码程序紧密联系：复杂格式缺乏应用程序支持则无意义，简单格式功能过弱则限制发展", "生物信息学中常见格式包括平面文件格式、XML格式和关系型数据库", "平面文件格式（Flat File）是纯文本格式，每行有字段标识符", "⚠️ 考点/易错点：平面文件格式的本质是纯文本（通常ASCII），其普及取决于是否有程序能编码/解码；易混点：格式与程序支持二者缺一不可，复杂格式无程序支持则无意义。"], "code": null, "check": {"q": "关于生物信息学中的数据格式，下列说法正确的是？", "o": ["A. 复杂全能格式即使缺乏应用程序支持也有意义", "B. 简单紧凑格式若操作功能过弱也会限制其发展和普及", "C. 数据格式与能够编码和解码数据的程序无关", "D. 平面文件格式通常使用二进制字符，不能包含 ASCII 扩展字符"], "a": "B", "e": "页面指出复杂全能格式若缺乏应用程序支持则无意义；简单紧凑格式若操作功能过弱也会限制发展和普及；数据格式与程序紧密联系；平面文件通常使用 ASCII 字符，也可包含 ASCII 扩展字符。"}, "cards": [{"front": "生物信息学中常见的数据存储格式有哪些？", "back": "平面文件格式、XML格式和关系型数据库。", "mnemonic": "平、X、关", "useImg": false}]}, {"i": 9, "sec": "第一节 生物学数据库简介", "title": "UniProt平面文件Entry示例与字段标识符", "notes": "本页以UniProtKB/Swiss-Prot中细胞色素c（CYC_HUMAN）条目为例，展示平面文件格式的具体结构。每行开头为两个字符组成的字段标识符，用于区分Entry的不同部分及其意义。示例中ID行标识条目唯一标识符CYC_HUMAN，并说明该条目经过审阅、蛋白质序列长度为105个氨基酸。AC行列出登录号，如P99999等。DT行记录日期信息，包括创建日期、序列版本和条目版本。DE行给出推荐名称RecName: Full=Cytochrome c。GN行给出基因名称CYCS及其同义词CYC。OS行标明物种为Homo sapiens（Human）。OC行描述分类学谱系，从真核生物、后生动物、脊索动物、脊椎动物等到人。OX行给出NCBI TaxID=9606。RN、RP、RX、RA等行开始描述参考文献信息。该页说明平面文件中每行由字段标识符引导，不同字段承载不同语义，是解析和索引Flat File的基础。", "page": 20, "level": "掌握", "img": "assets/img/ch02/p020.jpg", "anim": null, "fig": null, "points": ["UniProtKB/Swiss-Prot平面文件每行开头为两个字符组成的字段标识符", "ID行标识条目唯一标识符，并说明审阅状态和序列长度", "AC行列出登录号，DT行记录日期信息", "示例为细胞色素c（CYC_HUMAN）条目，序列长度105个氨基酸", "⚠️ 考点/易错点：UniProt平面文件每行开头两个字符是字段标识符（如ID、AC、DT、DE），ID行含条目名与序列长度，AC行是登录号；易错：ID与AC含义不同，ID是唯一标识符名，AC是登录号。"], "code": null, "check": {"q": "在 UniProt 平面文件示例中，ID 行 CYC_HUMAN 主要说明什么？", "o": ["A. 该条目的登录号为 CYC_HUMAN", "B. 该条目的唯一标识符为 CYC_HUMAN，并说明条目经过审阅、序列长度为105个氨基酸", "C. 该条目的物种为人类，但不包含序列长度信息", "D. 该条目的数据库交叉引用编号为 CYC_HUMAN"], "a": "B", "e": "页面说明 ID 行标识条目唯一标识符 CYC_HUMAN，并说明该条目经过审阅、蛋白质序列长度为105个氨基酸；AC 行才列出登录号。"}, "cards": [{"front": "UniProt平面文件中ID行和AC行分别表示什么？", "back": "ID行标识条目唯一标识符，并说明审阅状态和序列长度；AC行列出登录号。", "mnemonic": "ID标识，AC登录", "useImg": false}]}, {"i": 10, "sec": "第一节 生物学数据库简介", "title": "UniProt平面文件中的交叉引用、注释与关键词字段", "notes": "本页继续展示UniProt平面文件条目内容，重点包括CC、DR、PE、KW等字段。CC行表示注释信息，示例中包含版权声明，说明该条目由UniProt Consortium版权所有，并按Creative Commons Attribution-NoDerivs License分发。DR行表示数据库交叉引用，示例中多次出现EMBL数据库引用，格式通常为DR 数据库名; 登录号; 蛋白质ID; 状态; 分子类型，如Genomic_DNA或mRNA。这些交叉引用把UniProt条目与核酸序列数据库等外部资源关联起来。PE行表示蛋白质存在证据等级，示例中PE=1表示Evidence at protein level，即蛋白质水平证据。KW行列出关键词，如3D-structure、Acetylation、Apoptosis、Complete proteome、Direct protein sequencing、Disease mutation等，用于功能注释和检索。该页说明Flat File通过不同字段组织交叉引用、注释和关键词，便于数据整合与查询。", "page": 21, "level": "理解", "img": "assets/img/ch02/p021.jpg", "anim": null, "fig": null, "points": ["CC行表示注释信息，如版权声明和分发许可", "DR行表示数据库交叉引用，如EMBL数据库引用", "PE行表示蛋白质存在证据等级", "KW行表示关键词", "⚠️ 考点/易错点：DR行是数据库交叉引用，格式为“DR 数据库名; 登录号; 蛋白质ID; 状态; 分子类型”；CC是注释行，KW是关键词，PE是蛋白质存在证据等级，易混各字段缩写含义。"], "code": null, "check": {"q": "在 UniProt 平面文件中，DR 行通常表示什么？", "o": ["A. 日期信息", "B. 推荐名称", "C. 数据库交叉引用", "D. 关键词"], "a": "C", "e": "页面指出 DR 行表示数据库交叉引用，示例中多次出现 EMBL 数据库引用，格式通常为 DR 数据库名; 登录号; 蛋白质ID; 状态; 分子类型。"}, "cards": [{"front": "UniProt平面文件中CC行和DR行分别表示什么？", "back": "CC行表示注释信息；DR行表示数据库交叉引用。", "mnemonic": "CC注释，DR引用", "useImg": false}]}, {"i": 11, "sec": "第一节 生物学数据库简介", "title": "平面文件字段语义、重复子条目与语法分析", "notes": "本页总结平面文件Entry的字段语义和解析方法。AC行等提供Entry在之前或其他数据库中的唯一标识符；OS行表明蛋白质所属器官种类即序列来源。有些信息可跨越多行，如CC行包含多行注释；有些行可重复多次，例如每个参考文献由RN、RP、RC、RX、RA、RT和RL行组成，分别表示编号、参考位置、参考注释、参考交叉引用、作者、标题和被引用位置。这些重复组有时称为Subentry，有时单独放在主Entry之外。某些单行也可包含不同种类信息并用标签区分，如FT行定义序列特征，由特征关键字、序列范围或更多注释描述；CC行文本使用注释模块开始的结构。数据出版商通常提供可读格式规范，说明每行数据结构和语义。Flat File数据可用于解析和索引。语法分析是定义和提取指定文本特定部分或语法成分的计算手段，用计算机算法按句法或语法规则识别输入文本中有用部分；匹配失败则拒绝，匹配成功则分解为几部分。一种简单广泛使用的语法解析手段是基于正则表达式的分析。", "page": 22, "level": "掌握", "img": "assets/img/ch02/p022.jpg", "anim": null, "fig": null, "points": ["AC行等提供Entry在之前或其他数据库中的唯一标识符", "OS行表明蛋白质所属器官种类即序列来源", "有些信息可跨越多行，如CC行包含多行注释", "有些行可重复多次，如参考文献由RN、RP、RC、RX、RA、RT和RL行组成，这些重复组称为重复子条目", "⚠️ 考点/易错点：平面文件中可重复的行组（如参考文献的RN/RP/RC/RX/RA/RT/RL）称为Subentry；易错：多行信息（如CC）与重复组不同，解析时需区分跨行与重复。"], "code": null, "check": {"q": "关于平面文件 Entry 的字段语义和解析，下列说法正确的是？", "o": ["A. 每个参考文献由 RN、RP、RC、RX、RA、RT 和 RL 行组成，这些重复组有时称为 Subentry", "B. CC 行只能出现一次，不能跨越多行", "C. OS 行提供 Entry 在之前或其他数据库中的唯一标识符", "D. AC 行表明蛋白质所属器官种类即序列来源"], "a": "A", "e": "页面说明每个参考文献由 RN、RP、RC、RX、RA、RT 和 RL 行组成，分别表示编号、参考位置、参考注释、参考交叉引用、作者、标题和被引用位置，这些重复组有时称为 Subentry；CC 行可包含多行注释；AC 行提供唯一标识符；OS 行表明蛋白质所属器官种类。"}, "cards": [{"front": "平面文件中的重复子条目是什么？", "back": "有些行可重复多次，如参考文献由RN、RP、RC、RX、RA、RT和RL行组成，这些重复组称为重复子条目。", "mnemonic": "参考文献多行组，重复子条目", "useImg": false}]}, {"i": 12, "sec": "第二节 生物学数据库的数据存储格式", "title": "Perl 解析 Flat File 示例与 RDBMS 性能", "notes": "本页通过一个 Perl 例程说明如何从 UniProt Flat File 中提取主登录号和序列长度。程序逐行读取标准输入，遇到 ID 行时置标志 $newEntry=1；遇到 AC 行且标志为 1 时，输出 Primary accession 及捕获的登录号，并将标志清零；遇到 SQ 行时输出 sequence length 及捕获的序列长度。例程输出显示对多个 UniProt 条目依次得到主登录号和序列长度。该例说明 Flat File 是行导向、可编程解析的文本格式，适合用正则表达式提取字段。页末指出，生物信息学数据不仅数量增长，格式也常变化，因此需要 RDBMS 等系统获得可接受性能，同时 Flat File 格式细节会随项目合并和程序变化而改变。学习时应掌握 ID、AC、SQ 等行的含义，理解正则匹配与状态标志的配合，并认识 Flat File 与关系数据库在存储和检索上的差异。", "page": 23, "level": "掌握", "img": "assets/img/ch02/p023.jpg", "anim": null, "fig": null, "points": ["Perl例程逐行读取标准输入，遇到ID行时置标志$newEntry=1", "遇到AC行且标志为1时，输出Primary accession及捕获的登录号，并将标志清零", "遇到SQ行时输出sequence length及捕获的序列长度", "RDBMS性能：关系型数据库管理系统具有高性能、数据一致性等优点", "⚠️ 考点/易错点：Perl解析Flat File的典型逻辑：遇ID行置标志，遇AC行且标志为1时输出主登录号并清零标志，遇SQ行输出序列长度；易错：标志清零时机与只取主登录号（第一个AC）。"], "code": null, "check": {"q": "关于 Perl 解析 Flat File 示例，程序遇到哪一行时输出 sequence length？", "o": ["A. ID 行", "B. AC 行", "C. SQ 行", "D. DR 行"], "a": "C", "e": "页面说明程序逐行读取标准输入，遇到 ID 行时置标志 $newEntry=1；遇到 AC 行且标志为1时输出 Primary accession；遇到 SQ 行时输出 sequence length 及捕获的序列长度。"}, "cards": [{"front": "Perl解析Flat File时如何提取主登录号和序列长度？", "back": "逐行读取，遇到ID行置标志$newEntry=1；遇到AC行且标志为1时输出Primary accession及登录号并清零标志；遇到SQ行时输出sequence length及序列长度。", "mnemonic": "ID置标志，AC取登录，SQ取长度", "useImg": false}]}, {"i": 13, "sec": "第二节 生物学数据库的数据存储格式", "title": "常见序列格式：FASTA、SwissProt、GenBank", "notes": "本页说明序列格式因数据库和用途不同而不同，序列常被用户提取和再利用，因此格式对分析、显示和出版十分重要。许多生物信息学软件可自动区分并接受不同序列格式。序列格式在布局、每行序列字符形式、描述信息、行号等方面存在差异。图2-4以 UniProt/P32234 蛋白序列为例展示三种格式：FASTA 格式以大于号开头，包含 gi、sp、登录号、条目名和描述，随后是序列行；SwissProt 格式以 SQ 行给出序列长度、分子量和 CRC64 校验，序列按块排列，以 // 结束；GenBank 格式以 ORIGIN 开始，序列行带行号，末尾为 //。本页还指出，序列数据库条目不一定含实际序列，可能包含指导从其他条目构建序列的指令，例如 EMBL 核酸序列数据库中的 CO 行。学习时应能识别三种格式的头部、序列区和结束标志，并理解格式转换与自动识别的重要性。", "page": 24, "level": "掌握", "img": "assets/img/ch02/p024.jpg", "anim": null, "fig": "图2-4以UniProt/P32234蛋白序列为例展示三种格式：FASTA格式以大于号开头，包含gi、sp、登录号、条目名和描述，随后是序列；SwissProt和GenBank格式在布局、每行序列字符形式、描述信息、行号等方面存在差异。读图时注意比较三种格式的字段标识和序列排列方式。", "points": ["序列格式因数据库和用途不同而不同，对分析、显示和出版十分重要", "许多生物信息学软件可自动区分并接受不同序列格式", "FASTA格式以大于号开头，包含gi、sp、登录号、条目名和描述，随后是序列", "SwissProt和GenBank格式在布局、每行序列字符形式、描述信息、行号等方面存在差异", "⚠️ 考点/易错点：FASTA以“>”开头含gi、sp、登录号、条目名和描述；SwissProt以SQ行给出序列长度、分子量和CRC64；GenBank格式不同；易错：三种格式的起始标识与描述信息布局易混。"], "code": null, "check": {"q": "关于 FASTA、SwissProt、GenBank 等常见序列格式，下列说法正确的是？", "o": ["A. FASTA 格式以大于号开头，包含 gi、sp、登录号、条目名和描述，随后是序列行", "B. SwissProt 格式以大于号开头，不包含 SQ 行", "C. GenBank 格式与 FASTA 格式完全相同，仅描述信息不同", "D. 许多生物信息学软件不能自动区分不同序列格式，必须人工指定"], "a": "A", "e": "页面说明 FASTA 格式以大于号开头，包含 gi、sp、登录号、条目名和描述，随后是序列行；SwissProt 格式以 SQ 行给出序列长度、分子量和 CRC64 等；许多软件可自动区分并接受不同序列格式。"}, "cards": [{"front": "FASTA格式的基本特征是什么？", "back": "以大于号开头，包含gi、sp、登录号、条目名和描述，随后是序列。", "mnemonic": "大于号开头，描述加序列", "useImg": false}]}, {"i": 14, "sec": "第二节 生物学数据库的数据存储格式", "title": "PubMed XML 记录结构示例", "notes": "本页展示 PubMed 文献记录的 XML 片段，根元素为 MedlineCitation，含 Owner、Status 等属性。PMID 为文献唯一标识；Article 元素含 PubModel 属性，其下 Journal 包含 ISSN、JournalIssue、Title、ISOAbbreviation 等；JournalIssue 含 Volume、Issue、PubDate，PubDate 又含 Year、Month、Day。ArticleTitle 给出论文题名，Pagination 含 MedlinePgn 页码，Abstract 含 AbstractText 摘要，Affiliation 给出作者单位。该页说明 XML 用嵌套元素和属性表达文献元数据，结构清晰、可扩展，便于机器解析和交换。学习时应理解 XML 的树形结构：元素可嵌套，属性描述元素特性，文本内容位于元素之间。PubMed XML 是生物信息学中常用的 XML 资源之一，虽不直接包含序列数据，但为文献检索和基因组/蛋白质组数据库的参考文献链接提供基础。", "page": 25, "level": "理解", "img": "assets/img/ch02/p025.jpg", "anim": null, "fig": null, "points": ["PubMed文献记录XML根元素为MedlineCitation，含Owner、Status等属性", "PMID为文献唯一标识", "Article元素含PubModel属性，其下Journal包含ISSN、JournalIssue、Title、ISOAbbreviation等", "JournalIssue含Volume、Issue、PubDate等", "⚠️ 考点/易错点：PubMed XML根元素为MedlineCitation，含Owner、Status属性；PMID是文献唯一标识；Article含PubModel属性，其下Journal含ISSN、JournalIssue、Title、ISOAbbreviation；易错：各元素层级嵌套关系。"], "code": null, "check": {"q": "在 PubMed XML 记录中，PMID 元素的作用是什么？", "o": ["A. 表示期刊 ISSN", "B. 表示文献唯一标识", "C. 表示作者姓名", "D. 表示 MeSH 主题词"], "a": "B", "e": "页面说明 PubMed XML 片段根元素为 MedlineCitation，含 Owner、Status 等属性；PMID 为文献唯一标识。"}, "cards": [{"front": "PubMed XML记录的根元素是什么？", "back": "MedlineCitation。", "mnemonic": "根元素MedlineCitation", "useImg": false}]}, {"i": 15, "sec": "第二节 生物学数据库的数据存储格式", "title": "PubMed XML 的作者、期刊与 MeSH 主题词", "notes": "本页继续展示 PubMed XML 记录的后半部分，包括 AuthorList 中的 ForeName、Initials 等作者信息，Language 语言，MedlineJournalInfo 中的 Country、MedlineTA、NlmUniqueID、ISSNLinking 等期刊信息，以及 MeshHeadingList 主题词列表。每个 MeshHeading 含 DescriptorName 和 QualifierName，并用 MajorTopicYN 属性标明是否为主要主题。图2-5给出完整的 PubMed XML 例子。页末指出，XML 文档结构根据文件类型定义 DTD 组织，DTD 由 XML 文档作者自行定义，一个 DTD 定义一类遵从一系列规则的 XML 文档。学习时应掌握 XML 元素、属性、嵌套关系，理解 DTD 的作用是规定元素名称、出现顺序、出现次数和属性类型，从而保证 XML 文档结构一致、可验证。MeSH 主题词用于将文本索引到 PubMed 记录，并支持从不同术语层次检索文献。", "page": 26, "level": "理解", "img": "assets/img/ch02/p026.jpg", "anim": null, "fig": null, "points": ["AuthorList包含ForeName、Initials等作者信息", "Language表示语言", "MedlineJournalInfo包含Country、MedlineTA、NlmUniqueID、ISSNLinking等期刊信息", "MeshHeadingList为主题词列表，每个MeshHeading含DescriptorName等", "⚠️ 考点/易错点：PubMed XML中AuthorList含ForeName、Initials等作者信息，MedlineJournalInfo含Country、MedlineTA、NlmUniqueID、ISSNLinking，MeshHeadingList为主题词列表，每个MeshHeading含DescriptorName和QualifierName；易错：主题词由Descriptor与Qualifier两部分组成。"], "code": null, "check": {"q": "在 PubMed XML 记录中，MeshHeadingList 主要包含什么？", "o": ["A. 作者列表", "B. 期刊信息", "C. 主题词列表", "D. 语言信息"], "a": "C", "e": "页面说明 PubMed XML 后半部分包括 AuthorList、Language、MedlineJournalInfo 以及 MeshHeadingList 主题词列表；每个 MeshHeading 含 DescriptorName 和 QualifierName。"}, "cards": [{"front": "PubMed XML中MeshHeadingList表示什么？", "back": "主题词列表，每个MeshHeading含DescriptorName等。", "mnemonic": "Mesh主题词列表", "useImg": false}]}, {"i": 16, "sec": "第二节 生物学数据库的数据存储格式", "title": "PubMed XML 的 DTD 元素声明", "notes": "本页展示 PubMed XML 文件类型定义 DTD 的一部分，用 ELEMENT 声明元素及其内容模型。ArticleSet 包含一个或多个 Article；Article 依次包含 Journal、可选的 Replaces、ArticleTitle、VernacularTitle、FirstPage、LastPage、可重复的 ELocationID、可重复的 Language、AuthorList、GroupList、PublicationType、ArticleIdList、History、Abstract、OtherAbstract、CopyrightInformation、ObjectList、ArchiveCopySource 等。Journal 包含 PublisherName、JournalTitle、Issn、可选 Volume、可选 Issue、PubDate。PubDate 包含 Year、可选 Month、可选 Day、可选 Season，并用 ATTLIST 声明 PubStatus 属性，默认值为 ppublish。PCDATA 表示元素文本内容。学习时应理解 DTD 中逗号表示顺序、问号表示可选、星号表示零次或多次、加号表示一次或多次，以及 ATTLIST 定义属性。DTD 使 XML 文档结构可被机器验证，是 XML 数据交换的重要基础。", "page": 27, "level": "理解", "img": "assets/img/ch02/p027.jpg", "anim": null, "fig": null, "points": ["DTD用ELEMENT声明元素及其内容模型", "ArticleSet包含一个或多个Article", "Article依次包含Journal、可选的Replaces、ArticleTitle、VernacularTitle、FirstPage、LastPage、可重复的ELocationID等", "DTD定义了XML文档的结构和元素关系", "⚠️ 考点/易错点：PubMed XML 的 DTD 中 ArticleSet 可含一个或多个 Article，Article 内元素顺序固定且部分元素（如 ELocationID、Language）可重复，易考内容模型与出现次数约束。"], "code": null, "check": {"q": "关于 PubMed XML 的 DTD 元素声明，下列说法正确的是？", "o": ["A. ArticleSet 包含一个或多个 Article", "B. Article 只能包含 Journal，不能包含 ArticleTitle", "C. ELocationID 不能重复出现", "D. Language 只能出现一次"], "a": "A", "e": "页面说明 DTD 中 ArticleSet 包含一个或多个 Article；Article 依次包含 Journal、可选的 Replaces、ArticleTitle、VernacularTitle、FirstPage、LastPage、可重复的 ELocationID、可重复的 Language、AuthorList、GroupList 等。"}, "cards": [{"front": "DTD中ELEMENT声明的作用是什么？", "back": "声明元素及其内容模型，定义XML文档的结构和元素关系。", "mnemonic": "ELEMENT声明元素和内容模型", "useImg": false}]}, {"i": 17, "sec": "第二节 生物学数据库的数据存储格式", "title": "DTD 续、DOM 与 PubMed/MeSH 资源", "notes": "本页继续给出 DTD 声明，包括 FirstName 的 Empty 和 YN 属性、MiddleName、LastName、CollectiveName、Suffix、Affiliation 等元素，图2-6为 PubMed XML 文件的 DTD。随后说明 DOM 与 XML 相似，是通用的，对 DOM 对象操作的软件本质上处理 XML 数据；常见软件如网络浏览器提供 XML 无缝整合和 DOM 级编程支持，文档管理系统和搜索引擎也能以 DOM 兼容方式索引、搜索、回收信息。XML 广泛用于生物信息学，最常用资源是美国国家医学图书馆的 PubMed 和 MeSH 数据库。截至2017年11月，PubMed 已收录超过2900万篇引用文献，附摘要及原文链接，是医药学、生物学、遗传学和生物化学研究的重要第一手资料。许多基因组和蛋白质组数据库的参考文献链接到 PubMed。MeSH 提供完整术语分层结构，用于将文本索引至 PubMed 记录，并支持从不同术语层次搜索文本文档。学习时应理解 DOM 将 XML 文档表示为树形对象模型，便于程序遍历和操作；掌握 PubMed 与 MeSH 的关系及其在文献检索中的价值。", "page": 28, "level": "掌握", "img": "assets/img/ch02/p028.jpg", "anim": null, "fig": "图2-6为PubMed XML文件的DTD，展示了元素声明和内容模型。读图时注意ELEMENT声明中元素之间的包含关系和出现次数（如+、*、?）。", "points": ["DTD续包括FirstName的Empty和YN属性、MiddleName、LastName、CollectiveName、Suffix、Affiliation等元素", "图2-6为PubMed XML文件的DTD", "DOM与XML相似，是通用的，对DOM对象操作的软件本质上处理XML数据", "常见软件如PubMed/MeSH资源可用于处理XML数据", "⚠️ 考点/易错点：DTD 中 FirstName 声明为 Empty 并带 YN 属性，说明属性用于补充空元素信息；DOM 是通用 XML 编程接口，浏览器等软件可无缝整合 XML 并提供 DOM 级支持。"], "code": null, "check": {"q": "关于 DOM 与 XML 的关系，下列说法正确的是？", "o": ["A. DOM 与 XML 完全不同，对 DOM 对象操作的软件不能处理 XML 数据", "B. DOM 与 XML 相似，是通用的，对 DOM 对象操作的软件本质上处理 XML 数据", "C. DOM 只能用于 PubMed 数据库，不能用于其他 XML 数据", "D. 网络浏览器不支持 XML 与 DOM 级编程"], "a": "B", "e": "页面说明 DOM 与 XML 相似，是通用的，对 DOM 对象操作的软件本质上处理 XML 数据；常见软件如网络浏览器提供 XML 无缝整合和 DOM 级编程支持。"}, "cards": [{"front": "DOM与XML的关系是什么？", "back": "DOM与XML相似，是通用的，对DOM对象操作的软件本质上处理XML数据。", "mnemonic": "DOM操作XML", "useImg": false}]}, {"i": 18, "sec": "第三节 生物学数据库的检索", "title": "关系型数据库与数据库规范化", "notes": "本页承接第二章开头，重点介绍生物学数据库的关系型模型与规范化概念。规范化（normalization）指通过定义不同等级的表结构来减少数据冗余，其目标是在冗余与性能之间取得平衡；最佳方案取决于数据库系统类型、使用频率和常用登录方式。数据库建模的结果是数据库结构纲目（database schema），它定义每张表的每一列细节以及表与列之间的关系和约束。实现数据关联的系统称为关系型数据库管理系统（RDBMS），常见产品包括 Oracle、MySQL、Microsoft SQL Server 等，其中 MySQL 开源且适合中小型生物数据库。用户通过 SQL 语句进行添加、删除或查询。生物信息学中的关系型数据库实例有 Ensembl 和 Gene Ontology 数据库；Ensembl 由 EBI 与 Wellcome Trust Sanger Institute 联合开发，主要收录脊椎动物等真核生物基因组注释数据，可通过直接访问 MySQL 服务器获取。", "page": 29, "level": "掌握", "img": "assets/img/ch02/p029.jpg", "anim": null, "fig": null, "points": ["规范化（normalization）指通过定义不同等级的表结构来减少数据冗余", "规范化目标是在冗余与性能之间取得平衡，最佳方案取决于数据库系统类型、使用频率和常用登录方式", "数据库建模的结果是数据库结构纲目（database schema），定义每张表的每一列细节以及表与列之间的关系和约束", "关系型数据库与数据库规范化是本章第三节重点", "⚠️ 考点/易错点：规范化通过分级表结构减少冗余，但需在冗余与性能间平衡；数据库建模结果是数据库结构纲目（schema），RDBMS 是实现数据关联的系统。"], "code": null, "check": {"q": "关于数据库规范化（normalization），下列说法正确的是？", "o": ["A. 规范化的目标是完全消除冗余，不考虑性能", "B. 规范化指通过定义不同等级的表结构来减少数据冗余，其目标是在冗余与性能之间取得平衡", "C. 数据库建模的结果是数据库管理系统本身", "D. 实现数据关联的系统称为数据库结构纲目"], "a": "B", "e": "页面指出规范化指通过定义不同等级的表结构来减少数据冗余，其目标是在冗余与性能之间取得平衡；数据库建模的结果是数据库结构纲目（database schema）；实现数据关联的系统称为关系型数据库管理系统（RDBMS）。"}, "cards": [{"front": "什么是数据库规范化？", "back": "通过定义不同等级的表结构来减少数据冗余，目标是在冗余与性能之间取得平衡。", "mnemonic": "规范化减冗余，平衡性能", "useImg": false}]}, {"i": 19, "sec": "第三节 生物学数据库的检索", "title": "Entrez 数据库模型与全局检索", "notes": "本页介绍 NCBI 的 Entrez 检索系统。Entrez 是一个跨数据库检索平台，其数据库模型如图 2-7 所示，核心思想是记录之间通过预运算建立关联，例如核酸序列记录经 BLAST 预运算后带有相关序列（related sequence）链接。Entrez 提供全局检索（Global Search），网址为 http://www.ncbi.nlm.nih.gov/gquery/，页面列举全部可查询的 Entrez 数据库，分为 6 大类、共 38 个小类。第一类 Literature 包括 Books、PubMed 文献、PubMed Central 全文、MeSH 和 NLM 书目。用户在输入框输入关键词后点击 Search，返回结果会显示每个数据库中的命中数量；点击特定数据库即可查看该库结果。全局检索适合宽泛检索，但结果不精确；精确检索需针对特定数据库采用特殊方法。NCBI 主页搜索框旁的下拉菜单也可直接选择某个数据库，许多数据库能直接链接至 NCBI 主页。", "page": 30, "level": "理解", "img": "assets/img/ch02/p030.jpg", "anim": null, "fig": "图2-7为Entrez数据库模型，展示不同数据库记录之间的关联。读图时注意记录之间通过预运算建立的链接，如核酸序列与相关序列、蛋白质、结构等。", "points": ["Entrez是NCBI的跨数据库检索平台", "Entrez数据库模型核心思想是记录之间通过预运算建立关联，如核酸序列记录经BLAST预运算后带有相关序列链接", "Entrez提供全局检索（Global Search），网址为http://www.ncbi.nlm.nih.gov/gquery/", "Entrez可同时检索多个数据库", "⚠️ 考点/易错点：Entrez 是跨数据库检索平台，核心是记录间通过预运算建立关联（如 BLAST 预运算产生 related sequence 链接），并提供全局检索 gquery。"], "code": null, "check": {"q": "关于 NCBI 的 Entrez 检索系统，下列说法正确的是？", "o": ["A. Entrez 只能检索核酸序列数据库，不能跨数据库检索", "B. Entrez 是一个跨数据库检索平台，记录之间通过预运算建立关联", "C. Entrez 全局检索页面只列举核酸和蛋白质数据库", "D. Entrez 不提供全局检索功能"], "a": "B", "e": "页面说明 Entrez 是一个跨数据库检索平台，其数据库模型核心思想是记录之间通过预运算建立关联，例如核酸序列记录经 BLAST 预运算后带有相关序列链接；Entrez 提供全局检索，页面列举全部可查询的 Entrez 数据库，分为6类。"}, "cards": [{"front": "Entrez数据库模型的核心思想是什么？", "back": "记录之间通过预运算建立关联，例如核酸序列记录经BLAST预运算后带有相关序列链接。", "mnemonic": "预运算建关联", "useImg": false}]}, {"i": 20, "sec": "第三节 生物学数据库的检索", "title": "Entrez 布尔操作符与检索式构建", "notes": "本页展示 Entrez 全局检索页面（图 2-8）并讲解检索式构建。Entrez 查询关键字可以是单词、短语、句子、数据库标识符、基因标记或名字等。过于简单的搜索可能产生不可计数或零结果。Entrez 内置多种提高检索效率的特征，包括布尔操作符、查询语句和数据库可用标签，可手动输入，也可通过网络界面的限制、过滤和高级搜索完成。布尔操作符包括：AND，取两端短语同时出现的文档，即交集；OR，取两端任意一个短语出现的文档，即并集；NOT，取左边短语出现但右边短语不出现的文档，即差集。Entrez 要求 AND 必须大写，OR 和 NOT 虽不强制但建议大写。布尔操作符按从左至右顺序处理，括号可改变优先级，括号内部分优先作为一个单位处理。例如 promoters OR response elements NOT human AND mammals 中，response element 和 promoter 的关系会受括号影响。", "page": 31, "level": "掌握", "img": "assets/img/ch02/p031.jpg", "anim": null, "fig": "图2-8为Entrez全局检索页面，展示检索框和数据库选择。读图时注意检索框可输入关键词，下方可选择数据库或全部数据库。", "points": ["Entrez查询关键字可以是单词、短语、句子、数据库标识符、基因标记或名字等", "过于简单的搜索可能产生不可计数或零结果", "Entrez内置多种提高检索效率的特征，包括布尔操作符、查询语句和数据库可用标签", "布尔操作符包括：AND（取两端短语的交集）、OR（并集）、NOT（排除）", "⚠️ 考点/易错点：Entrez 布尔操作符 AND 为交集、OR 为并集、NOT 为排除；检索式过简可能导致结果不可计数或为零，需结合限制、过滤和高级搜索。"], "code": null, "check": {"q": "在 Entrez 布尔操作符中，NOT 的含义是什么？", "o": ["A. 取两端短语同时出现的文档，即交集", "B. 取两端任意一个短语出现的文档，即并集", "C. 取不包含 NOT 后面短语的文档", "D. 取两端短语必须按顺序相邻出现的文档"], "a": "C", "e": "页面说明布尔操作符包括：AND 取两端短语同时出现的文档，即交集；OR 取两端任意一个短语出现的文档，即并集；NOT 取不包含 NOT 后面短语的文档。"}, "cards": [{"front": "Entrez的布尔操作符有哪些？", "back": "AND（交集）、OR（并集）、NOT（排除）。", "mnemonic": "AND交，OR并，NOT排", "useImg": false}]}, {"i": 21, "sec": "第三节 生物学数据库的检索", "title": "Entrez 短语搜索、索引与域限定", "notes": "本页继续讲解 Entrez 检索规则。用空格连接的多个单词通常被视为用 AND 连接，如 tp53 mouse 表示 tp53 与 mouse 的交集。每个 Entrez 数据库有专门的索引列表，当短语与列表匹配时，Entrez 将其视为一个整体短语而非多个独立单词，例如 protein kinase c 被视为一个短语。不同数据库的索引列表及处理方式可能不同。引号可强制进行词组搜索，但需谨慎，因为引号要求文本完全匹配，可能漏掉相关记录；对于 Medical Subject Headings 或 Organism(Taxonomy) 等固定词组，加引号可避免被拆分。每个 Entrez 数据库建立各具特点的索引集，即域（field），有些域可随意书写，有些则严格控制，如 accession、PMID、MeSH 和 Organism。Entrez 默认全局搜索，可能产生大量不相关结果；例如在核酸数据库中以 horse 搜索会得到许多与“马”无关的记录，若目标是马这个物种，应加入特定域限定。", "page": 32, "level": "掌握", "img": "assets/img/ch02/p032.jpg", "anim": null, "fig": null, "points": ["用空格连接的多个单词通常被视为用AND连接，如tp53 mouse表示tp53与mouse的交集", "每个Entrez数据库有专门的索引列表，当短语与列表匹配时，Entrez将其视为一个整体短语而非多个独立单词", "不同数据库的索引列表及处理方式可能不同", "域限定可指定检索字段，如作者、期刊、日期等", "⚠️ 考点/易错点：空格连接的多个单词通常按 AND 处理；Entrez 各数据库有专门索引列表，匹配时会将短语视为整体，引号强制词组搜索但要求完全匹配，可能漏检。"], "code": null, "check": {"q": "在 Entrez 中，用空格连接的多个单词通常被视为？", "o": ["A. 用 OR 连接", "B. 用 NOT 连接", "C. 用 AND 连接", "D. 视为一个整体短语"], "a": "C", "e": "页面说明用空格连接的多个单词通常被视为用 AND 连接，如 tp53 mouse 表示 tp53 与 mouse 的交集；当短语与数据库索引列表匹配时，Entrez 才将其视为一个整体短语。"}, "cards": [{"front": "Entrez中多个空格连接的单词默认如何组合？", "back": "通常被视为用AND连接。", "mnemonic": "空格默认AND", "useImg": false}]}, {"i": 22, "sec": "第三节 生物学数据库的检索", "title": "MeSH 与物种域及查询自动映射", "notes": "本页以 PubMed 限制检索页面（图 2-11）为例，说明 MeSH 和物种域的特殊地位。在 PubMed 及传统生物分子数据库中，MeSH 和物种域使用严格的控制性词汇，并按层次分类。每条 PubMed 记录都被分配与文章主题相关的 MeSH 术语集；PubChem 部分记录也加入 MeSH 注释。几乎所有生物分子数据库记录都与物种及其系统分类学信息关联，即连接到 NCBI Taxonomy 数据库。由于这两个系统重要，查询在可能时会被自动映射到这两个库中的关键字，搜索词也可能被扩展或翻译成其他表示形式。某些数据库的其他域也可能有类似映射功能。例如查询 horse dopamine receptor D2（马多巴胺 D2 受体）在 PubMed 和 Entrez Protein 中会被系统自动转换为包含 horses、equidae、MeSH Terms、All Fields 等复杂表达，以提高查全率。", "page": 33, "level": "理解", "img": "assets/img/ch02/p033.jpg", "anim": null, "fig": "图2-11为PubMed限制检索页面，展示MeSH和物种域等限制选项。读图时注意可通过选择MeSH术语或物种来精确检索。", "points": ["在PubMed及传统生物分子数据库中，MeSH和物种域使用严格的控制性词汇，并按层次分类", "每条PubMed记录都被分配与文章主题相关的MeSH术语集", "PubChem部分记录也加入MeSH注释", "几乎所有生物分子数据库记录都与物种及其系统分类学信息关联", "⚠️ 考点/易错点：MeSH 和物种域使用严格受控词汇并层次分类，PubMed 记录被分配 MeSH 术语，生物分子数据库多关联 NCBI Taxonomy；查询可能自动映射到这些域。"], "code": null, "check": {"q": "关于 PubMed 中 MeSH 和物种域的特殊地位，下列说法正确的是？", "o": ["A. MeSH 和物种域使用严格的控制性词汇，并按层次分类", "B. 每条 PubMed 记录都被分配与文章主题相关的 MeSH 术语集，但 PubChem 记录不加入 MeSH 注释", "C. 生物分子数据库记录通常不与物种及系统分类学信息关联", "D. 查询在可能时不会自动映射到 MeSH 和物种域"], "a": "A", "e": "页面说明在 PubMed 及传统生物分子数据库中，MeSH 和物种域使用严格的控制性词汇，并按层次分类；每条 PubMed 记录都被分配与文章主题相关的 MeSH 术语集，PubChem 部分记录也加入 MeSH 注释；几乎所有生物分子数据库记录都与物种及其系统分类学信息关联，即连接到 NCBI Taxonomy 数据库；查询在可能时会自动映射到这两个系统。"}, "cards": [{"front": "MeSH和物种域在PubMed检索中有何特殊地位？", "back": "使用严格的控制性词汇，并按层次分类；每条PubMed记录都被分配与文章主题相关的MeSH术语集。", "mnemonic": "MeSH控制词汇，层次分类", "useImg": false}]}, {"i": 23, "sec": "第三节 生物学数据库的检索", "title": "Entrez 特殊检索规则与高级搜索", "notes": "本页总结 Entrez 的若干特殊检索规则。输入作者名时，完整输入姓氏再加不加标点的名字缩写（如 Lipman DJ）可自动映射到作者名域。输入特定数据库可识别的标识符可绕过普通索引直接得到结果，包括登记号（Accession）、序列标记的 GI 号、PubMed 标识符（PMID）和基因标识符。定冠词、非定冠词、连词和介词等虚词会被自动忽略，称为忽略字；标点也常被忽略，可能引起特定搜索词缺失，用引号包住可解决。搜索词结尾加单个“*”表示任意字符，即模糊查询，词干与“*”之间不应有空格；例如 hors* 可检索到 hors、hors4、horse、horse’s、horseradish 和 horst 等。模糊搜索在所有域中支持，适用于拼写不确定时，也可收集标识符范围，但仅使用前 600 个匹配结果。Entrez 高级搜索页可建立复杂精确的查询语句，图 2-13 展示 Entrez Protein 高级搜索页及其搜索构造器和历史搜索；历史搜索条目可合并搜索、移除历史条目、载入结果、显示查询，并可在 My NCBI 中保存查询。", "page": 34, "level": "掌握", "img": "assets/img/ch02/p034.jpg", "anim": null, "fig": null, "points": ["输入作者名时，完整输入姓氏再加不加标点的名字缩写（如Lipman DJ）可自动映射到作者名域", "输入特定数据库可识别的标识符可绕过普通索引直接得到结果，包括登记号（Accession）、GI号、PMID和基因标识符", "定冠词、非定冠词、连词和介词等虚词会被自动忽略，称为忽略字", "标点符号等也有特殊处理规则", "⚠️ 考点/易错点：作者名完整姓氏加名字缩写可自动映射到作者域；登记号、GI 号、PMID、基因标识符等可绕过普通索引直接检索；虚词和标点常被忽略，引号可解决，词尾单个“*”表截词。"], "code": null, "check": {"q": "在 Entrez 中，搜索词结尾加单个“*”表示什么？", "o": ["A. 精确匹配该词", "B. 通配符，表示任意字符或字符串", "C. 排除该词", "D. 将该词视为忽略字"], "a": "B", "e": "页面说明搜索词结尾加单个“*”表示通配符，可代表任意字符或字符串；定冠词、非定冠词、连词和介词等虚词会被自动忽略，称为忽略字。"}, "cards": [{"front": "Entrez中哪些标识符可绕过普通索引直接得到结果？", "back": "登记号（Accession）、GI号、PMID和基因标识符。", "mnemonic": "Accession、GI、PMID、基因ID", "useImg": false}]}, {"i": 24, "sec": "第三节 生物学数据库的检索", "title": "Entrez 检索结果的显示、发送与剪贴板/我的收藏", "notes": "本页继续介绍 NCBI Entrez 检索结果页面的常用功能。Display Settings 菜单用于设置结果的显示格式、每页显示条数和排序方式；这些选项在多个数据库中常独立存在，具体可用格式、排序和默认显示方式因数据库而异。搜索结果只有一条时，默认显示方式也因数据库而异。通常每页默认显示 20 条记录，排序默认为随机方式，这些选项可保存到 My NCBI。Send to 菜单用于把结果发送到 My NCBI 的“我的收藏”、NCBI 剪贴板或本地文件；发送到本地文件时，用户可自行指定记录格式和排序。默认情况下，Display Settings 和 Send to 对所有记录生效，除非用户通过记录左侧复选框指定个别记录。剪贴板是 NCBI 网站中临时存储搜索记录的位置，每个 Entrez 数据库的剪贴板相互独立，容量为 500 条记录，记录在 8 小时后失效。剪贴板有内容时，数据库主页右上角会出现链接；剪贴板视图与当前数据库页面相同，也具备 Display Settings、Send to 等功能。用户可逐条删除记录，或用复选框选中后点击“移除选中条目”，也可在未选择任何条目时清空剪贴板。“我的收藏”是 My NCBI 服务的一部分，用于永久存储记录。每个 Entrez 数据库还提供各种过滤器，用以将搜索结果减少至特定范围。", "page": 35, "level": "掌握", "img": "assets/img/ch02/p035.jpg", "anim": null, "fig": null, "points": ["Display Settings菜单用于设置结果的显示格式、每页显示条数和排序方式", "这些选项在多个数据库中常独立存在，具体可用格式、排序和默认显示方式因数据库而异", "搜索结果只有一条时，默认显示方式也因数据库而异", "通常每页默认显示20条记录，排序默认为随机方式，这些选项可保存到My NCBI", "⚠️ 考点/易错点：Entrez 检索结果页的 Display Settings 可设置显示格式、每页条数和排序，且这些选项在不同数据库中常相互独立；默认每页 20 条、默认随机排序，易与具体数据库默认格式混淆。"], "code": null, "check": {"q": "关于 NCBI Entrez 检索结果页面的 Display Settings 菜单，下列说法正确的是？", "o": ["A. 用于设置结果的显示格式、每页显示条数和排序方式", "B. 只能设置显示格式，不能设置每页条数", "C. 只能设置排序方式，不能设置显示格式", "D. 所有数据库的可用格式、排序和默认显示方式完全相同"], "a": "A", "e": "页面说明 Display Settings 菜单用于设置结果的显示格式、每页显示条数和排序方式；这些选项在多个数据库中常独立存在，具体可用格式、排序和默认显示方式因数据库而异。"}, "cards": [{"front": "Entrez检索结果页面Display Settings菜单可设置什么？", "back": "显示格式、每页显示条数和排序方式。", "mnemonic": "格式、条数、排序", "useImg": false}]}, {"i": 25, "sec": "第三节 生物学数据库的检索", "title": "Omictools 数据库/软件资源平台及其检索方式", "notes": "本页介绍 Omictools 这一生物信息学数据库与软件资源平台。由于生物信息学资源数量庞大，研究者难以判断资源优劣、数据可用性和当前状态，Omictools 提供平台供用户评价数据库或软件，便于后续研究者考察。用户可提交新的数据库或软件，平台接受领域专家手工审核数据库内容。未登录用户每月只能访问 10 次 Omictools 数据库页面。当时 Omictools 已有 92 名审核志愿者、超过 9000 名注册用户及超过 20000 条数据库及软件信息，每月都有新用户评论。检索途径主要有：第一，利用主页快速文本检索框，检索词与 Omictools 中所有数据库及软件的名称和描述匹配并返回结果；允许不完整输入，但错误输入或空格位置不当会导致查不到结果；不支持同义搜索，例如 circRNA 与 circular RNA 结果不同。在返回结果页可进一步筛选，筛选条目包括资源分类、操作系统、编写所用程序语言、操作界面和生物学技术，用户可通过下拉菜单选择查询项以缩小结果范围。图 2-14 为 Omictools 主界面，图 2-15 为查询结果页面筛选界面。", "page": 36, "level": "理解", "img": "assets/img/ch02/p036.jpg", "anim": null, "fig": null, "points": ["Omictools是生物信息学数据库与软件资源平台", "由于资源数量庞大，研究者难以判断资源优劣、数据可用性和当前状态，Omictools提供平台供用户评价数据库或软件", "用户可提交新的数据库或软件，平台接受领域专家手工审核数据库内容", "未登录用户每月只能访问10次Omictools数据库页面", "⚠️ 考点/易错点：Omictools 是数据库/软件资源评价平台，核心易考点是未登录用户每月仅能访问 10 次数据库页面，以及其依赖专家手工审核和用户评价。"], "code": null, "check": {"q": "关于 Omictools 平台，下列说法正确的是？", "o": ["A. 用户不能提交新的数据库或软件", "B. 平台接受领域专家手工审核数据库内容", "C. 未登录用户每月可无限次访问 Omictools 数据库页面", "D. Omictools 不提供用户评价数据库或软件的功能"], "a": "B", "e": "页面说明 Omictools 提供平台供用户评价数据库或软件；用户可提交新的数据库或软件，平台接受领域专家手工审核数据库内容；未登录用户每月只能访问10次 Omictools 数据库页面。"}, "cards": [{"front": "Omictools平台的主要功能是什么？", "back": "提供平台供用户评价数据库或软件，便于后续研究者考察；用户可提交新的数据库或软件，平台接受领域专家手工审核。", "mnemonic": "评价、提交、审核", "useImg": false}]}, {"i": 26, "sec": "第三节 生物学数据库的检索", "title": "Omictools 分类查询与 DATO 数据库在线查询平台", "notes": "本页首先展示 Omictools 的分类查询界面（图 2-16），可按 OMIC 等类别浏览资源。随后介绍 DATO（Database of Databases and Tools Online，http://bis.zju.edu.cn/DaTo2/index.html），它是目前规模最大的生物信息学数据库在线查询平台。DATO 收集所有在 PubMed 中有记录的数据库及工具，并对名称、描述等信息进行人工校对，以保证准确性；用户不需要登录即可访问网站全部内容。由于数据库快速更新，研究者在选择及查询数据库时常常无法准确找到所需信息或文献资源；若想查询最新最全面的信息，不仅需要近期相关文献，还要在多个数据库中选择和比对，并花费时间判断数据可信性、筛选高质量数据。解决这一问题的一个办法是同行评价引导，但科研用户通常活跃度很低，如 Omictools 中绝大部分条目都没有用户评价。为帮助用户选择，DATO 同样提供评价功能，并进一步整合期刊质量、引用数量、访问情况等信息，以帮助用户做出判断。DATO 主界面包含搜索栏和全球地图，显示所有收录数据库的地理信息概况（图 2-17）。在搜索栏最左侧下拉菜单中选择按特定项搜索，并在右侧搜索框内输入搜索内容，点击搜索按键，所得内容会即时反馈在下方。点击地图上的数字，则会进一步按当前所选地区展开。地图上的“G”标识代表链接可用，“B”标识代表此数据库或工具无法访问或正常使用。用户可点击搜索按钮左侧按钮来切换模糊搜索或精确搜索。点击“Advan”进入高级搜索。", "page": 37, "level": "理解", "img": "assets/img/ch02/p037.jpg", "anim": null, "fig": "图2-16为Omictools分类查询界面，可按OMIC等类别浏览资源。读图时注意左侧或顶部的分类导航，选择类别后可查看该类下的数据库或软件列表。", "points": ["Omictools分类查询界面可按OMIC等类别浏览资源", "DATO（Database of Databases and Tools Online）是目前规模最大的生物信息学数据库在线查询平台", "DATO收集所有在PubMed中发表过的生物信息学数据库和工具", "DATO网址为http://bis.zju.edu.cn/DaTo2/index.html", "⚠️ 考点/易错点：DATO 是目前规模最大的生物信息学数据库在线查询平台，收集 PubMed 中有记录的数据库及工具并人工校对；易与 Omictools 的平台定位混淆。"], "code": null, "check": {"q": "关于 DATO 平台，下列说法正确的是？", "o": ["A. DATO 是 Database of Databases and Tools Online，是目前规模最大的生物信息学数据库在线查询平台", "B. DATO 只收集在 PubMed 中无记录的数据库及工具", "C. DATO 不对名称、描述等信息进行人工校对", "D. DATO 用户必须登录才能进行查询"], "a": "A", "e": "页面说明 DATO（Database of Databases and Tools Online，http://bis.zju.edu.cn/DaTo2/index.html）是目前规模最大的生物信息学数据库在线查询平台；它收集所有在 PubMed 中有记录的数据库及工具，并对名称、描述等信息进行人工校对；用户不需登录即可查询。"}, "cards": [{"front": "DATO是什么？", "back": "Database of Databases and Tools Online，目前规模最大的生物信息学数据库在线查询平台，收集所有在PubMed中发表过的生物信息学数据库和工具。", "mnemonic": "DATO=数据库和工具在线查询", "useImg": false}]}, {"i": 27, "sec": "第三节 生物学数据库的检索", "title": "DATO 主界面、高级搜索与统计信息展示", "notes": "本页以三幅图展示 DATO 平台的主要界面。图 2-17 为 DATO 数据库主界面，包含搜索栏和全球地图，地图上以数字表示各地区收录数据库数量，点击数字可按地区展开；地图上的“G”标识代表链接可用，“B”标识代表数据库或工具无法访问或正常使用。图 2-18 为 DATO 高级搜索界面，用户可在搜索栏最左侧下拉菜单中选择按特定项搜索，如 PMID、Name、Description、URL、Status、Country 等字段，并在右侧搜索框内输入搜索内容，点击搜索后结果即时反馈在下方；高级搜索支持更精确的字段限定，也可切换模糊搜索或精确搜索。图 2-19 为 DATO 数据库统计信息展示，显示收录数据库及工具的数量、分类、访问状态等统计概况，帮助用户了解资源整体分布与可用性。DATO 通过人工校对名称和描述、整合期刊质量、引用数量、访问情况等信息，并提供评价功能，帮助用户在快速更新的生物信息学资源中做出选择。", "page": 38, "level": "了解", "img": "assets/img/ch02/p038.jpg", "anim": null, "fig": "图2-17为DATO数据库主界面，包含搜索栏和全球地图，地图上以数字表示各地区收录数据库数量，点击数字可按地区展开；地图上的“G”标识代表链接可用，“B”标识代表数据库或工具无法访问或正常使用。图2-18为DATO高级搜索界面，用户可在搜索栏最左侧下拉菜单中选择按特定项搜索，如PMID、Name等。读图时注意搜索栏和地图的交互功能。", "points": ["DATO主界面包含搜索栏和全球地图，地图上以数字表示各地区收录数据库数量，点击数字可按地区展开", "地图上的“G”标识代表链接可用，“B”标识代表数据库或工具无法访问或正常使用", "DATO高级搜索界面可在搜索栏最左侧下拉菜单中选择按特定项搜索，如PMID、Name等", "DATO还展示统计信息", "⚠️ 考点/易错点：DATO 主界面地图中数字表示各地区收录数据库数量，'G' 表示链接可用，'B' 表示无法访问或正常使用；高级搜索可按 PMID、Name、Description、URL、Status、Country 等字段检索。"], "code": null, "check": {"q": "在 DATO 主界面地图上，“B”标识代表什么？", "o": ["A. 链接可用", "B. 数据库或工具无法访问或正常使用", "C. 该地区收录数据库数量为0", "D. 该地区为高级搜索区域"], "a": "B", "e": "页面说明 DATO 主界面地图上以数字表示各地区收录数据库数量，点击数字可按地区展开；地图上的“G”标识代表链接可用，“B”标识代表数据库或工具无法访问或正常使用。"}, "cards": [{"front": "DATO主界面地图上的“G”和“B”标识代表什么？", "back": "“G”代表链接可用，“B”代表数据库或工具无法访问或正常使用。", "mnemonic": "G好B坏", "useImg": false}]}, {"i": 28, "sec": "第三节 生物学数据库的检索", "title": "本章思考题与参考文献", "notes": "本页为第二章“生物学数据库及其检索”的结尾部分，包含思考题和参考文献。思考题有三道：1. 一级数据库与二级数据库的区别是什么？一级数据库存储原始实验数据，如序列、结构等；二级数据库是在一级数据库基础上经过分析、整合或注释得到的数据库，如保守结构域、通路、聚类等。2. 数据库的 Flat File 和 XML 格式各有何特点？Flat File 为纯文本、字段固定、便于人工阅读和传统解析；XML 为结构化标记语言，层次清晰、便于程序解析和数据交换，但文件通常更冗长。3. Entrez 的检索途径有哪些？Entrez 是 NCBI 的集成检索系统，可跨多个数据库检索，支持关键词、字段限定、布尔逻辑、截词、限定条件、历史记录、剪贴板、My NCBI 等途径。参考文献列出本章引用的工具、算法和数据库相关文献，如 Aho 等关于编译原理、Altschul 等关于 BLAST、Appel 关于现代编译实现、Grune 和 Jacobs 关于解析技术、Higgins 和 Sharp 关于 CLUSTAL、IUPAC-IUB 关于氨基酸和肽命名等。这些文献为本章内容提供理论和方法学依据。", "page": 39, "level": "掌握", "img": "assets/img/ch02/p039.jpg", "anim": null, "fig": null, "points": ["一级数据库与二级数据库的区别：一级数据库存储原始实验数据，如序列、结构等；二级数据库是在一级数据库基础上经过分析、整合或注释得到的数据库，如保守结构域、通路、聚类等", "数据库的Flat File和XML格式各有特点：Flat File为纯文本、字段标识符固定、易于阅读和解析；XML为结构化、可扩展、适合数据交换", "本章参考文献列出了相关资源", "⚠️ 考点/易错点：一级数据库存原始实验数据，二级数据库是在一级数据库基础上分析整合或注释得到；Flat File 为纯文本、字段固定、便于人工阅读，XML 为结构化标记语言、层次清晰、便于程序解析。"], "code": null, "check": {"q": "根据本章思考题，一级数据库与二级数据库的区别是什么？", "o": ["A. 一级数据库存储分析整合后的注释数据，二级数据库存储原始实验数据", "B. 一级数据库存储原始实验数据，如序列、结构等；二级数据库是在一级数据库基础上经过分析、整合或注释得到的数据库", "C. 一级数据库和二级数据库都只存储原始实验数据", "D. 一级数据库只能存储序列，二级数据库只能存储结构"], "a": "B", "e": "页面思考题指出：一级数据库存储原始实验数据，如序列、结构等；二级数据库是在一级数据库基础上经过分析、整合或注释得到的数据库，如保守结构域、通路、聚类等。"}, "cards": [{"front": "一级数据库与二级数据库的区别是什么？", "back": "一级数据库存储原始实验数据，如序列、结构等；二级数据库是在一级数据库基础上经过分析、整合或注释得到的数据库，如保守结构域、通路、聚类等。", "mnemonic": "一级原始，二级加工", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_1", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "在数据库记录中，描述某一类数据特性或属性的类别称为：", "o": ["A. 值（value）", "B. 字段（field）", "C. 条目（entry）", "D. 记录（record）"], "a": "B", "e": "字段（field）是描述数据特性或属性的类别，如基因名、物种；值是字段的具体内容；记录/条目是描述一个实体的完整数据集合。", "kp": "ch02_s0_0"}, {"id": "ch02_mcq_2", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "下列属于一级数据库的是：", "o": ["A. RefSeq", "B. UniProt KnowledgeBase", "C. GenBank", "D. Pfam"], "a": "C", "e": "GenBank是典型的核酸序列一级数据库，存储实验原始数据。RefSeq和UniProt KnowledgeBase是二级数据库，Pfam是序列特征数据库。", "kp": "ch02_s0_1"}, {"id": "ch02_mcq_3", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "UniProt平面文件Entry中，表示Entry结束的符号是：", "o": ["A. //", "B. ##", "C. --", "D. **"], "a": "A", "e": "UniProt Flat File中，每个Entry以“//”表示结束。每行开头为两个字符的字段标识符，如ID、AC、DT等。", "kp": "ch02_s0_9"}, {"id": "ch02_mcq_4", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "关于平面文件格式（Flat File）的描述，错误的是：", "o": ["A. 通常使用ASCII字符", "B. 通用性强，便于跨平台传输", "C. 存储空间利用率通常优于关系型数据库表", "D. 检索时可能需要通读整个文件"], "a": "C", "e": "平面文件在存储空间需求上并不占优势，关系型数据库表或XML文件可能更紧凑。其优势在于通用性和可解析性。", "kp": "ch02_s0_8"}, {"id": "ch02_mcq_5", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "二级数据库与一级数据库的主要区别在于：", "o": ["A. 二级数据库只存储核酸序列", "B. 二级数据库在一级数据库基础上经计算加工并增加人工注释", "C. 二级数据库不包含任何注释", "D. 二级数据库只能通过实验获得数据"], "a": "B", "e": "二级数据库在一级数据库信息基础上进行计算加工并增加人为注释，如RefSeq、UniProt KnowledgeBase。其注释可能由程序自动计算，使用时需谨慎。", "kp": "ch02_s0_1"}, {"id": "ch02_mcq_6", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "Entrez系统中，预先运算好的与某记录相似的其他记录之间的连接称为：", "o": ["A. 硬连接（hard link）", "B. 软连接（soft link）", "C. 超链接（hyperlink）", "D. 外键（foreign key）"], "a": "B", "e": "软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录，如核酸序列经BLAST预运算后的相关序列。硬连接指点击圆圈显示的不同数据库间的链接。", "kp": "ch02_s0_19"}, {"id": "ch02_mcq_7", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "下列不属于Entrez全局检索第一类（Literature）的是：", "o": ["A. PubMed", "B. PubMed Central", "C. MeSH", "D. GenBank"], "a": "D", "e": "Entrez全局检索第一类Literature包括书籍、PubMed、PubMed Central、MeSH和NLM书目。GenBank属于核酸序列数据库，不在Literature类。", "kp": "ch02_s0_19"}, {"id": "ch02_mcq_8", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "关于BLAST的描述，正确的是：", "o": ["A. BLAST保证找到最优比对结果", "B. BLAST基于全局比对算法", "C. BLAST是启发式局部比对工具，输出E值", "D. BLAST只能用于核酸序列检索"], "a": "C", "e": "BLAST是基于局部比对的启发式算法，不保证最优比对，输出比对得分、E值和相似性百分比。它有blastn、blastp等多种程序，可用于核酸和蛋白质检索。", "kp": "ch02_s0_13"}, {"id": "ch02_mcq_9", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "Ensembl数据库通常建议通过什么方式访问？", "o": ["A. 直接读取平面文件", "B. 专用Perl API", "C. FTP下载全部数据", "D. 电子邮件查询"], "a": "B", "e": "Ensembl数据可直接访问MySQL服务器，但由于结构纲目复杂，通常建议通过专用Perl API访问。它由EBI与Wellcome Trust Sanger Institute联合开发。", "kp": "ch02_s0_18"}, {"id": "ch02_mcq_10", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "构建系统发生树时，基于距离矩阵快速构建的方法是：", "o": ["A. 最大似然法（ML）", "B. 贝叶斯推断", "C. 邻接法（NJ）", "D. 最大简约法（MP）"], "a": "C", "e": "邻接法（NJ）基于距离矩阵快速构建系统发生树。ML和贝叶斯基于概率模型，计算量大但统计基础更严谨；MP基于最小进化步数假设。", "kp": "ch02_s0_2"}], "judge": [{"id": "ch02_judge_1", "modI": 0, "q": "字段是属性类别，值是具体内容，二者可以混淆。", "a": "错", "e": "字段是属性类别，值是具体内容，二者不可混淆；记录与条目同义。", "kp": "ch02_s0_0"}, {"id": "ch02_judge_2", "modI": 0, "q": "平面文件格式即纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode。", "a": "对", "e": "平面文件格式即纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode；数据被组织为若干Entry（记录/条目），每个Entry描述一个数据实体。", "kp": "ch02_s0_8"}, {"id": "ch02_judge_3", "modI": 0, "q": "二级数据库的注释等同于实验证实。", "a": "错", "e": "二级库注释不等于实验证实；自动计算注释可能误导，使用时需谨慎。", "kp": "ch02_s0_1"}, {"id": "ch02_judge_4", "modI": 0, "q": "UniProt的Flat File Entry以“//”表示Entry结束。", "a": "对", "e": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束。", "kp": "ch02_s0_9"}, {"id": "ch02_judge_5", "modI": 0, "q": "关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询。", "a": "对", "e": "关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高。", "kp": "ch02_s0_18"}, {"id": "ch02_judge_6", "modI": 0, "q": "Entrez中，各数据库内部数据间存在硬连接（hard link），又称neighbor，指预先运算好的与某记录相似的其他记录。", "a": "错", "e": "Entrez中，各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）。", "kp": "ch02_s0_19"}, {"id": "ch02_judge_7", "modI": 0, "q": "在Entrez检索中，布尔操作符须大写，字段标签须用方括号。", "a": "对", "e": "易错点：布尔操作符须大写；字段标签须用方括号；不同数据库支持的字段与语法不同，需查阅各自帮助文档。", "kp": "ch02_s0_20"}, {"id": "ch02_judge_8", "modI": 0, "q": "BLAST是精确算法，保证找到最优比对。", "a": "错", "e": "BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_13"}, {"id": "ch02_judge_9", "modI": 0, "q": "E值越小越显著。", "a": "对", "e": "BLAST与FASTA均输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。", "kp": "ch02_s0_0"}, {"id": "ch02_judge_10", "modI": 0, "q": "多序列比对质量不影响系统发生树的可信度。", "a": "错", "e": "MSA质量直接影响树的可信度；不同方法可能得到不同拓扑结构，需结合自举值（bootstrap）评估支持率。", "kp": "ch02_s0_4"}], "fill": [{"id": "ch02_fill_1", "modI": 0, "q": "数据库的基本单位是________，一条记录描述一个实体；记录由若干________组成，字段是描述属性的类别；________是字段的具体内容。", "a": "记录,字段,值", "kp": "ch02_s0_0"}, {"id": "ch02_fill_2", "modI": 0, "q": "生物学数据库采用4种结构类型：________、关系型数据库、面向对象数据库和基于Internet的________。", "a": "平面文件,XML", "kp": "ch02_s0_0"}, {"id": "ch02_fill_3", "modI": 0, "q": "按存放数据类型，生物学数据库可分为：序列数据库（如GenBank、Swiss-Prot）、三维结构数据库（如________）、文献数据库（如NCBI PubMed）、序列特征数据库（如PROSITE、Pfam）、基因组图谱数据库（如MapViewer、Ensembl）、表达谱数据库等。", "a": "PDB", "kp": "ch02_s0_1"}, {"id": "ch02_fill_4", "modI": 0, "q": "一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库________。", "a": "PDB", "kp": "ch02_s0_1"}, {"id": "ch02_fill_5", "modI": 0, "q": "UniProt的Flat File Entry由一系列文本行组成，以“________”表示Entry结束；每行开头为两个字符的字段标识符，其中ID行给出唯一标识、状态与序列长度（氨基酸残基数）；AC行列出登录号；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI ________。", "a": "//,TaxID", "kp": "ch02_s0_9"}, {"id": "ch02_fill_6", "modI": 0, "q": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类；第一类Literature包括书籍、PubMed文献、PubMed Central全文、MeSH和NLM书目；全局检索可对检索词进行多库宽泛检索，但结果不精确；精确检索须针对特定数据库，采用特殊方法，如使用________操作符连接一个或多个搜索域。", "a": "布尔", "kp": "ch02_s0_19"}, {"id": "ch02_fill_7", "modI": 0, "q": "在单个Entrez数据库主页可进行更精确的检索，常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等；检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”；易错点：布尔操作符须________；字段标签须用________。", "a": "大写,方括号", "kp": "ch02_s0_20"}, {"id": "ch02_fill_8", "modI": 0, "q": "序列相似性检索是数据库检索的核心任务之一；BLAST基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx；FASTA是另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略；两者均输出比对得分、E值（期望值）和相似性百分比；E值越________越显著。", "a": "小", "kp": "ch02_s0_19"}], "short": [{"id": "ch02_short_1", "modI": 0, "q": "简述生物学数据库按存储内容层次的分类，并举例说明一级数据库与二级数据库的区别。", "a": "按存储内容层次分为一级数据库、二级数据库和专用数据库。一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。二级数据库在一级数据库基础上经计算加工并增加人工注释，如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）。二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎；二级库注释不等于实验证实。", "kp": "ch02_s0_1"}, {"id": "ch02_short_2", "modI": 0, "q": "简述UniProt平面文件Entry的结构与常见字段标识符的含义。", "a": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束；每行开头为两个字符的字段标识符：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献。理解字段标识符是解析平面文件、编写脚本提取信息的基础。", "kp": "ch02_s0_9"}, {"id": "ch02_short_3", "modI": 0, "q": "简述Entrez全局检索与单库精确检索的区别，并列举单库精确检索的常用策略。", "a": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类；用户在输入框输入关键词点击Search，页面返回查询结果在各数据库中的数量，点击特定数据库即可查看该库结果；全局检索可对检索词进行多库宽泛检索，但结果不精确。精确检索须针对特定数据库，采用特殊方法，如使用布尔操作符连接一个或多个搜索域。在单个Entrez数据库主页可进行更精确的检索，常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等；检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”。易错点：布尔操作符须大写；字段标签须用方括号；不同数据库支持的字段与语法不同，需查阅各自帮助文档。", "kp": "ch02_s0_19"}, {"id": "ch02_short_4", "modI": 0, "q": "简述BLAST与FASTA的异同及使用时的注意事项。", "a": "相同点：BLAST与FASTA均属序列相似性检索程序，基于局部比对，输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。不同点：BLAST（Basic Local Alignment Search Tool）通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx；FASTA采用不同的词长与打分策略。注意事项：BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_13"}, {"id": "ch02_short_5", "modI": 0, "q": "简述多序列比对与系统发生分析的关系及常用方法与注意事项。", "a": "多序列比对（MSA）将多条序列按同源位点对齐，常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等；比对结果可用于识别保守区、构建系统发生树。系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断；NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨。注意事项：MSA质量直接影响树的可信度；不同方法可能得到不同拓扑结构，需结合自举值（bootstrap）评估支持率。", "kp": "ch02_s0_2"}], "calc": [{"id": "ch02_calc_1", "modI": 0, "q": "论述生物学数据库检索中数据格式的通用性与紧凑性权衡，并结合平面文件、关系型数据库和XML说明其优缺点。", "a": "信息存储需控制两方面：数据编译为字节的方式（数据格式）以及能编码/解码该数据的程序。二者紧密相关：复杂全能格式若无现成程序支持则无意义；过于简单紧凑的格式又限制数据操作功能。平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。因此格式选择需在通用性、可解析性、存储效率与传输效率之间权衡，这是生物信息学数据管理面临的难题之一。", "steps": "1. 数据格式与程序支持的关系；2. 平面文件的通用性与空间利用率；3. 关系型表或XML的紧凑性；4. 网络传输时紧凑性的重要性；5. 格式选择的权衡。", "kp": "ch02_s0_8"}, {"id": "ch02_calc_2", "modI": 0, "q": "论述序列数据库检索中的常见问题与注意事项，并说明如何提高检索效率与结果可靠性。", "a": "使用序列数据库检索时需注意：①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。掌握这些要点可提高检索效率与结果可靠性。", "steps": "1. 数据库版本与更新日期；2. 冗余与参考序列选择；3. 注释质量与实验证据；4. 物种与分类学信息；5. 人工核查；6. 序列格式兼容性。", "kp": "ch02_s0_19"}], "term": [{"id": "ch02_term_1", "modI": 0, "term": "Database", "def": "按一定结构组织、统一管理的数据集合，便于检索与调用；基本单位是记录（record/entry），一条记录描述一个实体（如一条序列、一个蛋白质）；记录由若干字段（field）组成，字段是描述属性的类别，如基因名、物种、创建日期；值（value）是字段的具体内容。", "kp": "ch02_s0_26"}, {"id": "ch02_term_2", "modI": 0, "term": "Flat file database", "def": "以纯文本（通常ASCII，也可含扩展ASCII或Unicode）保存的数据库；数据组织为若干Entry（记录/条目），每个Entry描述一个数据实体；正文行中每列对应明确定义的格式；优势是通用性强、跨平台、便于FTP或电子邮件传输；缺点是存储空间利用率不占优，网络传输时紧凑性成为瓶颈。", "kp": "ch02_s0_12"}, {"id": "ch02_term_3", "modI": 0, "term": "Relational database", "def": "将数据组织为二维表，行对应记录、列对应字段；通过主键与外键建立表间关联；支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高；常见实例有Ensembl和Gene Ontology数据库。", "kp": "ch02_s0_12"}, {"id": "ch02_term_4", "modI": 0, "term": "XML", "def": "可扩展标记语言，用成对标签描述数据的层次结构；兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换；但文件较冗长。", "kp": "ch02_s0_14"}, {"id": "ch02_term_5", "modI": 0, "term": "Primary database", "def": "属档案数据库（archive），内容主要是实验原始数据及基本说明；如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。", "kp": "ch02_s0_12"}, {"id": "ch02_term_6", "modI": 0, "term": "Secondary database", "def": "在一级数据库基础上经计算加工并增加人工注释；如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）；二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎；二级库注释不等于实验证实。", "kp": "ch02_s0_18"}, {"id": "ch02_term_7", "modI": 0, "term": "UniProt flat file entry", "def": "由一系列文本行组成，以“//”表示Entry结束；每行开头为两个字符的字段标识符：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献；理解字段标识符是解析平面文件、编写脚本提取信息的基础。", "kp": "ch02_s0_9"}, {"id": "ch02_term_8", "modI": 0, "term": "Entrez", "def": "由NCBI开发维护，是目前应用最广泛的生物学数据库检索系统之一；利用公共数据库各记录间本身存在的逻辑关系，从多种类型数据的文本信息中找到所需信息；Entrez数据库模型中，圆圈表示各数据库，颜色深浅表示数据量多少；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）；各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录，例如核酸序列经BLAST预运算后每条记录都有相关序列（related sequence）。", "kp": "ch02_s0_19"}, {"id": "ch02_term_9", "modI": 0, "term": "SRS", "def": "Sequence Retrieval System，另一常用生物学数据库检索系统，最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库；核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航；与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转。", "kp": "ch02_s0_0"}, {"id": "ch02_term_10", "modI": 0, "term": "BLAST", "def": "Basic Local Alignment Search Tool，基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列；常用程序包括blastn、blastp、blastx、tblastn、tblastx；输出比对得分、E值（期望值）和相似性百分比；E值越小越显著；BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_13"}, {"id": "ch02_term_11", "modI": 0, "term": "FASTA", "def": "另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略；输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。", "kp": "ch02_s0_13"}, {"id": "ch02_term_12", "modI": 0, "term": "Multiple sequence alignment (MSA)", "def": "将多条序列按同源位点对齐，常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等；比对结果可用于识别保守区、构建系统发生树；MSA质量直接影响树的可信度。", "kp": "ch02_s0_12"}]}], "mcq": [{"id": "ch02_mcq_1", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "在数据库记录中，描述某一类数据特性或属性的类别称为：", "o": ["A. 值（value）", "B. 字段（field）", "C. 条目（entry）", "D. 记录（record）"], "a": "B", "e": "字段（field）是描述数据特性或属性的类别，如基因名、物种；值是字段的具体内容；记录/条目是描述一个实体的完整数据集合。", "kp": "ch02_s0_0"}, {"id": "ch02_mcq_2", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "下列属于一级数据库的是：", "o": ["A. RefSeq", "B. UniProt KnowledgeBase", "C. GenBank", "D. Pfam"], "a": "C", "e": "GenBank是典型的核酸序列一级数据库，存储实验原始数据。RefSeq和UniProt KnowledgeBase是二级数据库，Pfam是序列特征数据库。", "kp": "ch02_s0_1"}, {"id": "ch02_mcq_3", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "UniProt平面文件Entry中，表示Entry结束的符号是：", "o": ["A. //", "B. ##", "C. --", "D. **"], "a": "A", "e": "UniProt Flat File中，每个Entry以“//”表示结束。每行开头为两个字符的字段标识符，如ID、AC、DT等。", "kp": "ch02_s0_9"}, {"id": "ch02_mcq_4", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "关于平面文件格式（Flat File）的描述，错误的是：", "o": ["A. 通常使用ASCII字符", "B. 通用性强，便于跨平台传输", "C. 存储空间利用率通常优于关系型数据库表", "D. 检索时可能需要通读整个文件"], "a": "C", "e": "平面文件在存储空间需求上并不占优势，关系型数据库表或XML文件可能更紧凑。其优势在于通用性和可解析性。", "kp": "ch02_s0_8"}, {"id": "ch02_mcq_5", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "二级数据库与一级数据库的主要区别在于：", "o": ["A. 二级数据库只存储核酸序列", "B. 二级数据库在一级数据库基础上经计算加工并增加人工注释", "C. 二级数据库不包含任何注释", "D. 二级数据库只能通过实验获得数据"], "a": "B", "e": "二级数据库在一级数据库信息基础上进行计算加工并增加人为注释，如RefSeq、UniProt KnowledgeBase。其注释可能由程序自动计算，使用时需谨慎。", "kp": "ch02_s0_1"}, {"id": "ch02_mcq_6", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "Entrez系统中，预先运算好的与某记录相似的其他记录之间的连接称为：", "o": ["A. 硬连接（hard link）", "B. 软连接（soft link）", "C. 超链接（hyperlink）", "D. 外键（foreign key）"], "a": "B", "e": "软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录，如核酸序列经BLAST预运算后的相关序列。硬连接指点击圆圈显示的不同数据库间的链接。", "kp": "ch02_s0_19"}, {"id": "ch02_mcq_7", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "下列不属于Entrez全局检索第一类（Literature）的是：", "o": ["A. PubMed", "B. PubMed Central", "C. MeSH", "D. GenBank"], "a": "D", "e": "Entrez全局检索第一类Literature包括书籍、PubMed、PubMed Central、MeSH和NLM书目。GenBank属于核酸序列数据库，不在Literature类。", "kp": "ch02_s0_19"}, {"id": "ch02_mcq_8", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "关于BLAST的描述，正确的是：", "o": ["A. BLAST保证找到最优比对结果", "B. BLAST基于全局比对算法", "C. BLAST是启发式局部比对工具，输出E值", "D. BLAST只能用于核酸序列检索"], "a": "C", "e": "BLAST是基于局部比对的启发式算法，不保证最优比对，输出比对得分、E值和相似性百分比。它有blastn、blastp等多种程序，可用于核酸和蛋白质检索。", "kp": "ch02_s0_13"}, {"id": "ch02_mcq_9", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "Ensembl数据库通常建议通过什么方式访问？", "o": ["A. 直接读取平面文件", "B. 专用Perl API", "C. FTP下载全部数据", "D. 电子邮件查询"], "a": "B", "e": "Ensembl数据可直接访问MySQL服务器，但由于结构纲目复杂，通常建议通过专用Perl API访问。它由EBI与Wellcome Trust Sanger Institute联合开发。", "kp": "ch02_s0_18"}, {"id": "ch02_mcq_10", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "构建系统发生树时，基于距离矩阵快速构建的方法是：", "o": ["A. 最大似然法（ML）", "B. 贝叶斯推断", "C. 邻接法（NJ）", "D. 最大简约法（MP）"], "a": "C", "e": "邻接法（NJ）基于距离矩阵快速构建系统发生树。ML和贝叶斯基于概率模型，计算量大但统计基础更严谨；MP基于最小进化步数假设。", "kp": "ch02_s0_2"}], "judge": [{"id": "ch02_judge_1", "modI": 0, "q": "字段是属性类别，值是具体内容，二者可以混淆。", "a": "错", "e": "字段是属性类别，值是具体内容，二者不可混淆；记录与条目同义。", "kp": "ch02_s0_0"}, {"id": "ch02_judge_2", "modI": 0, "q": "平面文件格式即纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode。", "a": "对", "e": "平面文件格式即纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode；数据被组织为若干Entry（记录/条目），每个Entry描述一个数据实体。", "kp": "ch02_s0_8"}, {"id": "ch02_judge_3", "modI": 0, "q": "二级数据库的注释等同于实验证实。", "a": "错", "e": "二级库注释不等于实验证实；自动计算注释可能误导，使用时需谨慎。", "kp": "ch02_s0_1"}, {"id": "ch02_judge_4", "modI": 0, "q": "UniProt的Flat File Entry以“//”表示Entry结束。", "a": "对", "e": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束。", "kp": "ch02_s0_9"}, {"id": "ch02_judge_5", "modI": 0, "q": "关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询。", "a": "对", "e": "关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高。", "kp": "ch02_s0_18"}, {"id": "ch02_judge_6", "modI": 0, "q": "Entrez中，各数据库内部数据间存在硬连接（hard link），又称neighbor，指预先运算好的与某记录相似的其他记录。", "a": "错", "e": "Entrez中，各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）。", "kp": "ch02_s0_19"}, {"id": "ch02_judge_7", "modI": 0, "q": "在Entrez检索中，布尔操作符须大写，字段标签须用方括号。", "a": "对", "e": "易错点：布尔操作符须大写；字段标签须用方括号；不同数据库支持的字段与语法不同，需查阅各自帮助文档。", "kp": "ch02_s0_20"}, {"id": "ch02_judge_8", "modI": 0, "q": "BLAST是精确算法，保证找到最优比对。", "a": "错", "e": "BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_13"}, {"id": "ch02_judge_9", "modI": 0, "q": "E值越小越显著。", "a": "对", "e": "BLAST与FASTA均输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。", "kp": "ch02_s0_0"}, {"id": "ch02_judge_10", "modI": 0, "q": "多序列比对质量不影响系统发生树的可信度。", "a": "错", "e": "MSA质量直接影响树的可信度；不同方法可能得到不同拓扑结构，需结合自举值（bootstrap）评估支持率。", "kp": "ch02_s0_4"}], "fill": [{"id": "ch02_fill_1", "modI": 0, "q": "数据库的基本单位是________，一条记录描述一个实体；记录由若干________组成，字段是描述属性的类别；________是字段的具体内容。", "a": "记录,字段,值", "kp": "ch02_s0_0"}, {"id": "ch02_fill_2", "modI": 0, "q": "生物学数据库采用4种结构类型：________、关系型数据库、面向对象数据库和基于Internet的________。", "a": "平面文件,XML", "kp": "ch02_s0_0"}, {"id": "ch02_fill_3", "modI": 0, "q": "按存放数据类型，生物学数据库可分为：序列数据库（如GenBank、Swiss-Prot）、三维结构数据库（如________）、文献数据库（如NCBI PubMed）、序列特征数据库（如PROSITE、Pfam）、基因组图谱数据库（如MapViewer、Ensembl）、表达谱数据库等。", "a": "PDB", "kp": "ch02_s0_1"}, {"id": "ch02_fill_4", "modI": 0, "q": "一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库________。", "a": "PDB", "kp": "ch02_s0_1"}, {"id": "ch02_fill_5", "modI": 0, "q": "UniProt的Flat File Entry由一系列文本行组成，以“________”表示Entry结束；每行开头为两个字符的字段标识符，其中ID行给出唯一标识、状态与序列长度（氨基酸残基数）；AC行列出登录号；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI ________。", "a": "//,TaxID", "kp": "ch02_s0_9"}, {"id": "ch02_fill_6", "modI": 0, "q": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类；第一类Literature包括书籍、PubMed文献、PubMed Central全文、MeSH和NLM书目；全局检索可对检索词进行多库宽泛检索，但结果不精确；精确检索须针对特定数据库，采用特殊方法，如使用________操作符连接一个或多个搜索域。", "a": "布尔", "kp": "ch02_s0_19"}, {"id": "ch02_fill_7", "modI": 0, "q": "在单个Entrez数据库主页可进行更精确的检索，常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等；检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”；易错点：布尔操作符须________；字段标签须用________。", "a": "大写,方括号", "kp": "ch02_s0_20"}, {"id": "ch02_fill_8", "modI": 0, "q": "序列相似性检索是数据库检索的核心任务之一；BLAST基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx；FASTA是另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略；两者均输出比对得分、E值（期望值）和相似性百分比；E值越________越显著。", "a": "小", "kp": "ch02_s0_19"}], "short": [{"id": "ch02_short_1", "modI": 0, "q": "简述生物学数据库按存储内容层次的分类，并举例说明一级数据库与二级数据库的区别。", "a": "按存储内容层次分为一级数据库、二级数据库和专用数据库。一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。二级数据库在一级数据库基础上经计算加工并增加人工注释，如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）。二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎；二级库注释不等于实验证实。", "kp": "ch02_s0_1"}, {"id": "ch02_short_2", "modI": 0, "q": "简述UniProt平面文件Entry的结构与常见字段标识符的含义。", "a": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束；每行开头为两个字符的字段标识符：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献。理解字段标识符是解析平面文件、编写脚本提取信息的基础。", "kp": "ch02_s0_9"}, {"id": "ch02_short_3", "modI": 0, "q": "简述Entrez全局检索与单库精确检索的区别，并列举单库精确检索的常用策略。", "a": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类；用户在输入框输入关键词点击Search，页面返回查询结果在各数据库中的数量，点击特定数据库即可查看该库结果；全局检索可对检索词进行多库宽泛检索，但结果不精确。精确检索须针对特定数据库，采用特殊方法，如使用布尔操作符连接一个或多个搜索域。在单个Entrez数据库主页可进行更精确的检索，常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等；检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”。易错点：布尔操作符须大写；字段标签须用方括号；不同数据库支持的字段与语法不同，需查阅各自帮助文档。", "kp": "ch02_s0_19"}, {"id": "ch02_short_4", "modI": 0, "q": "简述BLAST与FASTA的异同及使用时的注意事项。", "a": "相同点：BLAST与FASTA均属序列相似性检索程序，基于局部比对，输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。不同点：BLAST（Basic Local Alignment Search Tool）通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx；FASTA采用不同的词长与打分策略。注意事项：BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_13"}, {"id": "ch02_short_5", "modI": 0, "q": "简述多序列比对与系统发生分析的关系及常用方法与注意事项。", "a": "多序列比对（MSA）将多条序列按同源位点对齐，常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等；比对结果可用于识别保守区、构建系统发生树。系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断；NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨。注意事项：MSA质量直接影响树的可信度；不同方法可能得到不同拓扑结构，需结合自举值（bootstrap）评估支持率。", "kp": "ch02_s0_2"}], "calc": [{"id": "ch02_calc_1", "modI": 0, "q": "论述生物学数据库检索中数据格式的通用性与紧凑性权衡，并结合平面文件、关系型数据库和XML说明其优缺点。", "a": "信息存储需控制两方面：数据编译为字节的方式（数据格式）以及能编码/解码该数据的程序。二者紧密相关：复杂全能格式若无现成程序支持则无意义；过于简单紧凑的格式又限制数据操作功能。平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。因此格式选择需在通用性、可解析性、存储效率与传输效率之间权衡，这是生物信息学数据管理面临的难题之一。", "steps": "1. 数据格式与程序支持的关系；2. 平面文件的通用性与空间利用率；3. 关系型表或XML的紧凑性；4. 网络传输时紧凑性的重要性；5. 格式选择的权衡。", "kp": "ch02_s0_8"}, {"id": "ch02_calc_2", "modI": 0, "q": "论述序列数据库检索中的常见问题与注意事项，并说明如何提高检索效率与结果可靠性。", "a": "使用序列数据库检索时需注意：①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。掌握这些要点可提高检索效率与结果可靠性。", "steps": "1. 数据库版本与更新日期；2. 冗余与参考序列选择；3. 注释质量与实验证据；4. 物种与分类学信息；5. 人工核查；6. 序列格式兼容性。", "kp": "ch02_s0_19"}], "term": [{"id": "ch02_term_1", "modI": 0, "term": "Database", "def": "按一定结构组织、统一管理的数据集合，便于检索与调用；基本单位是记录（record/entry），一条记录描述一个实体（如一条序列、一个蛋白质）；记录由若干字段（field）组成，字段是描述属性的类别，如基因名、物种、创建日期；值（value）是字段的具体内容。", "kp": "ch02_s0_26"}, {"id": "ch02_term_2", "modI": 0, "term": "Flat file database", "def": "以纯文本（通常ASCII，也可含扩展ASCII或Unicode）保存的数据库；数据组织为若干Entry（记录/条目），每个Entry描述一个数据实体；正文行中每列对应明确定义的格式；优势是通用性强、跨平台、便于FTP或电子邮件传输；缺点是存储空间利用率不占优，网络传输时紧凑性成为瓶颈。", "kp": "ch02_s0_12"}, {"id": "ch02_term_3", "modI": 0, "term": "Relational database", "def": "将数据组织为二维表，行对应记录、列对应字段；通过主键与外键建立表间关联；支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高；常见实例有Ensembl和Gene Ontology数据库。", "kp": "ch02_s0_12"}, {"id": "ch02_term_4", "modI": 0, "term": "XML", "def": "可扩展标记语言，用成对标签描述数据的层次结构；兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换；但文件较冗长。", "kp": "ch02_s0_14"}, {"id": "ch02_term_5", "modI": 0, "term": "Primary database", "def": "属档案数据库（archive），内容主要是实验原始数据及基本说明；如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。", "kp": "ch02_s0_12"}, {"id": "ch02_term_6", "modI": 0, "term": "Secondary database", "def": "在一级数据库基础上经计算加工并增加人工注释；如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）；二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎；二级库注释不等于实验证实。", "kp": "ch02_s0_18"}, {"id": "ch02_term_7", "modI": 0, "term": "UniProt flat file entry", "def": "由一系列文本行组成，以“//”表示Entry结束；每行开头为两个字符的字段标识符：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献；理解字段标识符是解析平面文件、编写脚本提取信息的基础。", "kp": "ch02_s0_9"}, {"id": "ch02_term_8", "modI": 0, "term": "Entrez", "def": "由NCBI开发维护，是目前应用最广泛的生物学数据库检索系统之一；利用公共数据库各记录间本身存在的逻辑关系，从多种类型数据的文本信息中找到所需信息；Entrez数据库模型中，圆圈表示各数据库，颜色深浅表示数据量多少；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）；各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录，例如核酸序列经BLAST预运算后每条记录都有相关序列（related sequence）。", "kp": "ch02_s0_19"}, {"id": "ch02_term_9", "modI": 0, "term": "SRS", "def": "Sequence Retrieval System，另一常用生物学数据库检索系统，最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库；核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航；与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转。", "kp": "ch02_s0_0"}, {"id": "ch02_term_10", "modI": 0, "term": "BLAST", "def": "Basic Local Alignment Search Tool，基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列；常用程序包括blastn、blastp、blastx、tblastn、tblastx；输出比对得分、E值（期望值）和相似性百分比；E值越小越显著；BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_13"}, {"id": "ch02_term_11", "modI": 0, "term": "FASTA", "def": "另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略；输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。", "kp": "ch02_s0_13"}, {"id": "ch02_term_12", "modI": 0, "term": "Multiple sequence alignment (MSA)", "def": "将多条序列按同源位点对齐，常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等；比对结果可用于识别保守区、构建系统发生树；MSA质量直接影响树的可信度。", "kp": "ch02_s0_12"}], "preview": {"main": "本章介绍生物学数据库的类型、内容与结构，以及通过Entrez和SRS进行综合检索。重点包括一级与二级数据库、NAR数据库与网络服务器分类、重要站点NCBI/EBI、Flat File/XML/关系型数据库等存储格式，以及Entrez检索规则与Omictools/DATO资源平台。", "questions": ["生物学数据库按存放数据类型可分为哪些类型？一级数据库与二级数据库有何区别？", "NAR数据库专辑和网络服务器专辑如何分类？它们对查找生物信息学资源有什么帮助？", "Flat File、XML和关系型数据库三种数据存储格式各有什么特点？分别适用于什么场景？", "Entrez检索中布尔操作符、短语索引、域限定和自动映射等规则如何影响检索结果？", "Omictools和DATO平台分别提供什么功能？如何利用它们评价和查找数据库或软件资源？"]}, "appcards": [{"front": "应用/分析型问题：某研究者想查找与“alcoholic disease”相关的生物学数据库，直接用公共搜索引擎搜索时结果出现歧义。请分析原因，并给出更可靠的资源查找策略。", "back": "原因：公共搜索引擎对多个检索词的默认组合关系不同，可能按短语、交集或并集处理，导致结果歧义；关键词不唯一。策略：①若已知准确资源名称或简称别名，直接使用名称检索；②利用NAR数据库专辑和网络服务器专辑，按结构、基因组、代谢与信号途径等分类查找；③使用重要门户站点如NCBI、EBI；④使用Omictools、DATO等数据库/软件资源平台，按类别或高级搜索查找并参考用户评价与可用状态。", "points": "公共搜索引擎歧义原因；已知名称/别名；NAR专辑分类；NCBI/EBI门户；Omictools/DATO平台", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：比较生物学数据库中的Flat File、XML和关系型数据库三种数据存储格式，并说明各自适用场景。", "back": "Flat File：纯文本、字段标识符开头、结构简单紧凑，便于人工阅读和简单程序解析，如UniProt、GenBank、FASTA；但复杂查询和跨记录关联能力弱。XML：通用、结构化、可嵌套，适合表达复杂记录如PubMed文献，需DTD定义元素，DOM等软件可处理；但文件较冗长。关系型数据库：通过表、列、关系和约束存储，支持规范化减少冗余，适合大批量数据存储、复杂检索和跨表关联；但设计需权衡冗余与性能。", "points": "Flat File特点与例子；XML特点与例子；关系型数据库特点；规范化与性能权衡；适用场景", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：在Entrez中检索“protein kinase c mouse”，系统会如何解析？请说明Entrez的短语索引、布尔操作符和域限定规则。", "back": "Entrez通常将空格连接的多个单词视为AND连接，因此“protein kinase c mouse”可能被解析为protein AND kinase AND c AND mouse；但每个Entrez数据库有专门索引列表，当短语与列表匹配时，Entrez将其视为整体短语，例如“protein kinase c”被视为一个短语。布尔操作符包括AND、OR、NOT，可手动输入或通过限制、过滤、高级搜索完成。域限定可用数据库可用标签限定字段，如作者名、MeSH、物种域等；输入作者名如Lipman DJ可自动映射到作者名域。", "points": "空格默认AND；短语索引匹配；布尔操作符AND/OR/NOT；域限定与标签；作者名自动映射；MeSH/物种域", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：一级数据库与二级数据库有何区别？请结合NAR数据库专辑分类举例说明。", "back": "一级数据库存储原始实验数据，如序列、结构等，例如GenBank、UniProt、PDB。二级数据库是在一级数据库基础上经过分析、整合或注释得到的数据库，如保守结构域、通路、聚类等。NAR数据库专辑按结构、基因组、代谢与信号途径等分类：结构数据库包括小分子结构、碳水化合物结构、核酸结构、蛋白质结构；基因组数据库包括通用基因组学、病毒、原核、单细胞真核、真菌、无脊椎动物等；代谢与信号途径也属相关分类。", "points": "一级数据库定义与例子；二级数据库定义与例子；NAR分类维度；结构/基因组/代谢与信号途径举例", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}]};